INSERT INTO modules (code, name_th_short, name_en_short, name_th, name_en, desc_th, desc_en, sort_order) VALUES
  ('PO', 'จัดซื้อ', 'Purchasing', 'ระบบใบสั่งซื้อ (PO)', 'Purchase Order System', 'เปรียบเทียบราคาคู่ค้าและออกใบสั่งซื้อ (PO) พร้อมระบบแจ้งเตือนเมื่อการใช้จ่ายเกินงบประมาณที่ตั้งไว้', 'Simplify purchasing and supplier evaluation. Improve procurement speed, accuracy, and control.', 1),
  ('IC', 'คลังสินค้า', 'Inventory', 'ระบบควบคุมสินค้าคงคลัง (IC)', 'Inventory Control System', 'ติดตามการเบิก-จ่ายวัสดุรายโครงการ และตรวจสอบยอดวัสดุคงเหลือแบบ Real-time เพื่อป้องกันการสูญหาย คุมต้นทุนการเบิกของได้', 'Monitor receiving, stock movements, and project transfers. Improve traceability and inventory accuracy.', 2),
  ('AP', 'เจ้าหนี้/จ่าย', 'Payables', 'ระบบบัญชี (AP)', 'Accounting System — Payables', 'บันทึกข้อมูลบัญชีรับ-จ่ายและภาษีที่เชื่อมโยงกับต้นทุนโครงการโดยตรง เพื่อความถูกต้องและแม่นยำสูงสุด', 'Manage payables, receivables, billing, and payments efficiently. Gain better accuracy and financial control.', 3),
  ('FA', 'ทรัพย์สิน', 'Fixed Assets', 'ระบบทรัพย์สินถาวร (FA)', 'Fixed Asset System', 'ทำทะเบียนทรัพย์สินและคำนวณค่าเสื่อมราคาอัตโนมัติ พร้อมติดตามการโอนย้ายทรัพย์สินระหว่างโครงการอย่างเป็นระบบ', 'Track assets, maintenance, and depreciation with ease. Keep records accurate and up to date.', 4),
  ('PM', 'โครงการ', 'Projects', 'ระบบจัดการโครงการ (PM)', 'Project Management System', 'สรุปภาพรวมสถานะโครงการแบบ Dashboard เปรียบเทียบแผนงานและต้นทุนจริงสำหรับผู้บริหาร', 'Track project progress and key updates in one view. Support faster, better management decisions.', 5),
  ('OF', 'เบิกจ่าย', 'Office Service', 'ระบบบริการสำนักงาน (OF)', 'Office Service System', 'จัดการใบขอซื้อ (PR) เบิกเงินสดย่อย และติดตามผลงานผู้รับเหมาจากหน้างานได้ทันทีผ่านมือถือ', 'Handle internal requests, subcontractor workflows, and approvals faster. Keep progress claims organized and controlled.', 6),
  ('GL', 'บัญชีแยกประเภท', 'General Ledger', 'ระบบสมุดรายวันทั่วไป (GL)', 'General Ledger System', 'รักษาระเบียนทางการเงินให้แม่นและจัดระเบียบได้ดี สนับสนุนการรายงานและการ reconciliation ที่ราบรื่น', 'Keep financial records accurate and well organized. Support smooth reporting and reconciliation.', 7),
  ('AR', 'ลูกหนี้/รับ', 'Receivables', 'ระบบบัญชี (AR)', 'Accounting System — Receivables', 'บันทึกข้อมูลบัญชีรับ-จ่ายและภาษีที่เชื่อมโยงกับต้นทุนโครงการโดยตรง เพื่อความถูกต้องและแม่นยำสูงสุด', 'Manage payables, receivables, billing, and payments efficiently. Gain better accuracy and financial control.', 8),
  ('BD', 'งบประมาณ', 'Bidding', 'ระบบการประมูล (BD)', 'Bidding System', 'วางแผนงบประมาณจาก BOQ และกำหนดรหัสต้นทุน (Cost Code) เพื่อเปรียบเทียบกำไร-ขาดทุนก่อนเริ่มโครงการ', 'Manage tenders, budgets, and bid evaluations in one place. Award projects with greater confidence.', 9),
  ('FIN', 'การเงิน', 'Finance', 'ระบบการเงิน (FIN)', 'Finance System', 'วิเคราะห์กระแสเงินสด (Cash Flow) และรายงานสถานะการรับ-จ่ายเงินของทุกโครงการได้ในหน้าจอเดียว ดูรายละเอียดชัดเจนว่ายอดเงินมาจากเอกสารฉบับใด', 'Monitor cash flow and financial performance clearly. Plan ahead with better financial visibility.', 10),
  ('SE', 'ตั้งค่าระบบ', 'Settings', 'ตั้งค่าระบบ (SE)', 'System Settings', 'กำหนดค่าระบบ ข้อมูลหลัก และสิทธิ์การเข้าถึง', 'Configure system preferences, master data, and access rights.', 11);
INSERT INTO sop_meta (title, subtitle, manual, version, effective, scope, purpose, notes, updated_at) VALUES
  ('VCB-MANGO ERP Standard Operating Procedure', 'ระเบียบปฏิบัติมาตรฐาน · กลุ่มวิจิตรภัณฑ์ก่อสร้าง', 'VCB-MANGO ERP Manual 14.3.68', 'v1.0 (Revised)', 'เมษายน 2569', 'บุคลากรทุกคนที่ใช้งานระบบ VCB-MANGO ERP', 'เอกสารนี้กำหนดระเบียบปฏิบัติมาตรฐาน (SOP) สำหรับสถานการณ์ที่เกิดขึ้นบ่อยในการใช้งานระบบ VCB-MANGO ERP ครอบคลุม 32 กรณีศึกษาซึ่งสะท้อนปัญหาที่เกิดขึ้นจริงในกระบวนการ PO, IC, AP, FA, PM, OF, GL, AR และโมดูลที่เกี่ยวข้อง วัตถุประสงค์หลักคือ เพื่อลดความผิดพลาดในการบันทึกข้อมูล สร้างความสม่ำเสมอในการปฏิบัติงาน และเสริมสร้างการควบคุมภายในที่มีประสิทธิภาพ SOP นี้ถือเป็นนโยบายบริษัทที่บังคับใช้กับบุคลากรทุกคนที่มีสิทธิ์ใช้งานระบบ ERP', ARRAY['เอกสารนี้จัดทำขึ้นตาม VCB-MANGO ERP Manual 14.3.68 โดยอ้างอิงกรณีปัญหาจริงที่เกิดขึ้นในระบบ', 'ข้อ 18 (Machine Overhaul): ยังต้องกำหนดมูลค่าขั้นต่ำที่ชัดเจนแทน "xxx ล้าน" ก่อนใช้งานเป็นนโยบายจริง', 'SOP นี้ให้ถือเป็นนโยบายบริษัทที่มีผลบังคับใช้ทันทีหลังได้รับการอนุมัติจากผู้บริหาร', 'หากพบข้อขัดแย้งระหว่าง SOP นี้กับการปฏิบัติจริง ให้แจ้งแผนกระบบ/บัญชีทันทีเพื่อทบทวนและปรับปรุง', 'สัญลักษณ์  [✓] = ยืนยันสอดคล้องกับ ERP Manual 14.3.68  |  [!] = จุดที่ต้องปรับปรุงหรือกำหนดเพิ่มเติม'], '2026-08-27T12:40:10.959Z');
INSERT INTO scenarios (no, module, display_no, title_th, title_en, problem, ref, note, date_added) VALUES
  (1, 'PO', 'PO-1', 'กรณีการทำใบลดยอด PO ที่มีการชำระเงินไปแล้ว', 'PO Decrement', 'เดิมบริษัทไม่มีแนวปฏิบัติในการลดยอดหรือยกเลิกใบสั่งซื้อ (PO) ที่ไม่มีการรับสินค้าเพิ่มเติมจากปริมาณที่เปิดไว้ ส่งผลให้มียอดคงค้างของใบสั่งซื้อในระบบเป็นจำนวนมาก ส่งผลกระทบต่อการประมวลผลของข้อมูลในระบบ บริษัทจึงกำหนดให้มีขั้นตอนการจัดทำใบลดยอดใบสั่งซื้อ (PO Decrement) และการออกใบลดหนี้ (Credit Note) ในกรณีที่เกี่ยวข้องเพื่อปรับปรุงข้อมูลตามขั้นตอนดังต่อไปนี้', 'ERP Manual 14.3.68 – บทที่ 4 (PO)', '', '1 เมษายน 2569'),
  (2, 'PO', 'PO-2', 'กรณีการเปิด PO คลุมเพื่อส่งทำตั๋ว / ทะยอยเอาของเข้า / แบ่งจ่ายบางส่วน', 'Blanket PO for Partial Delivery / Partial Payment', 'เนื่องจากตามนโยบายของธนาคารกำหนดให้ต้องมีการเปิดใบสั่งซื้อ (PO) เพื่อประกอบหลักฐานการทำตั๋วสัญญาใช้เงินในแต่ละครั้ง หากเปิดใบสั่งซื้อล่วงหน้าก่อนกำหนดการที่จะใช้ของ และแผนกบัญชีเผลอนำไปตั้งหนี้ อาจเกิดความเสี่ยงต่อการชำระเงินให้แก่ร้านค้าก่อนกำหนด จึงขอให้ดำเนินการตามขั้นตอนดังต่อไปนี้', 'ERP Manual 14.3.68 – บทที่ 4 (PO)', '', '1 เมษายน 2569'),
  (3, 'PO', 'PO-3', 'กรณีการเปิด PO และภายหลังมีการปรับเปลี่ยนราคา', 'PO–Invoice Price Mismatch', 'เดิมเมื่อบริษัททำการเปิด PO ในลักษณะคลุมปริมาณสินค้าและ ต่อมาร้านค้ามีการแจ้งปรับเปลี่ยนราคาสินค้าในภายหลัง ส่งผลให้ปริมาณวัสดุที่รับ (PO Receive) และปริมาณวัสดุที่นำเข้าคลัง (IC Receive) ไม่สอดคล้องกัน รวมถึงราคาที่ระบุในใบกำกับภาษีอาจไม่สอดคล้องกับราคาตามใบสั่งซื้อเช่นในกรณี ปูน ที่ส่งใบกำกับภาษี 7 วันหลังการส่งสินค้า จึงให้ดำเนินการตามขั้นตอนดังต่อไปนี้', 'ERP Manual 14.3.68 – บทที่ 4 (PO)', 'โดยปกติแล้วกรณี 3 และ 4 จะไม่เกิดขึ้นเนื่องจากร้านค้าจะยืนราคาตามใบสั่งซื้อ ดังนั้นจะเกิดขึ้นเฉพาะ PO ที่เปิดแล้วไม่ยืนราคา เช่น หิน / ทราย ที่มีการเปลี่ยนแปลงบ่อยจากราคาน้ำมัน', '1 เมษายน 2569'),
  (4, 'OF', 'OF-1', 'กรณีการเลือกประเภทรายการใน Module OF: Petty Cash / Advance / Other', 'OF Type Selection', 'เดิมบริษัทไม่ได้ใช้ OF อย่างเต็มรูปแบบ และทำรายการทุกประเภทที่ไม่ใช่ PO/WO เป็น OF หมวด Other ทั้งหมด ทำให้ค่าใช้จ่ายต่าง ๆ ไม่ได้ถูกแยกประเภทตามชนิดเอกสาร โดยเฉพาะยอดเงินสดย่อย เคลียร์เงินสดย่อย ทำให้ข้อมูลไม่เอื้อต่อการวิเคราะห์ตามรูปแบบอันควร', 'ERP Manual 14.3.68 – บทที่ 3 (OF)', 'ให้ยึดถือว่าเอกสาร OF ที่ถูกสร้างและผ่านการกดอนุมัติในระบบ ERP เป็นเอกสารอนุมัติทางการเพียงรูปแบบเดียวของบริษัท และให้ใส่ข้อมูลให้ถูกต้องครบถ้วน ห้ามผู้จัดทำใช้ใบปะหน้ากระดาษ / Memo เพื่อเป็นหลักฐานในการทำจ่ายแทนใบ OF ยกเว้นในกรณีฉุกเฉิน', '1 เมษายน 2569'),
  (5, 'OF', 'OF-2', 'กรณีการตั้งวงเงินสดย่อยเพื่อใช้ในโครงการ', 'Petty Cash/Petty Cash Clearance', 'เดิมบริษัทไม่ได้ใช้ OF อย่างเต็มรูปแบบ และทำรายการทุกประเภทที่ไม่ใช่ PO/WO เป็น OF หมวด Other ทั้งหมด ทำให้ค่าใช้จ่ายต่าง ๆ ไม่ได้ถูกแยกประเภทตามชนิดเอกสาร เพื่อปรับปรุงมาตรฐานการบันทึกรายการบัญชีที่ไม่ได้ผ่านระบบ PR/PO ให้เกิดความถูกต้องตามประเภทเอกสารที่แท้จริง แยกหมวดหมู่ยอดเงินสดย่อยและการเคลียร์เงินสดย่อยอย่างเป็นระบบ เพื่อนำข้อมูลไปวิเคราะห์ต้นทุนโครงการ', 'ERP Manual 14.3.68 – บทที่ 3 (OF) | บทที่ 6 (AP)', '', '1 เมษายน 2569'),
  (6, 'AP', 'AP-1', 'กรณีการโอนเงินภายในระหว่างบัญชีบริษัท/กิจการร่วมค้า', 'Bank Transfer & Intercompany Transfer Policy', 'แก้ไขปัญหาตัวเลขวิเคราะห์บิดเบือนในระบบจากการใช้การโอน 5 ขั้นตอนแบบเดิม โดยปรับมาใช้รูปแบบ Check-Transfer 3 ขั้นตอน ในระบบ AP (ไม่มีการทำใบเตรียมจ่าย APP) เพื่อรักษาความถูกต้องของข้อมูลวิเคราะห์ทางการเงินและบัญชี', 'ERP Manual 14.3.68 – บทที่ 6 (AP)', '', '1 เมษายน 2569'),
  (7, 'IC', 'IC-1', 'นโยบายการตั้งค่าคลังสินค้าและประเภทการเบิกใช้', 'Warehouse & Area Setup', 'เดิมบริษัทยังไม่มีการแบ่งหรือกำหนดวัตถุประสงค์การตั้ง Warehouse อย่างชัดเจน ทำให้ไม่สามารถตรวจสอบตำแหน่งและรายละเอียดวัสดุในคลังได้อย่างแม่นยำ', 'ERP Manual 14.3.68 – บทที่ 5 (IC)', '', '1 เมษายน 2569'),
  (8, 'IC', 'IC-2', 'นโยบายการควบคุมหน่วยนับวัสดุและการแปลงหน่วย', 'Unit of Measure & Conversion Control', 'เพื่อควบคุมมาตรฐานหน่วยนับของวัสดุ (Unit Code) ให้มีความสอดคล้องกันตลอดทั้งกระบวนการ ตั้งแต่ขั้นตอนการจัดทำงบประมาณ (Budget) การจัดซื้อ (PR/PO) ไปจนถึงการรับของเข้าคลัง (IC Receive) เพื่อป้องกันปัญหาการปัดเศษทศนิยมจากการแปลงหน่วยในระบบ ซึ่งส่งผลกระทบต่อความถูกต้องของยอดสต๊อกคงเหลือ (Stock Balance)', 'ERP Manual 14.3.68 – บทที่ 5 (IC)', '', '1 เมษายน 2569'),
  (9, 'IC', 'IC-3', 'กรณีการปรับปรุงยอดสินค้าในคลัง', 'IC Balance Adjustment', 'เพื่อกำหนดแนวทางและขั้นตอนที่ถูกต้องในการแก้ไขหรือปรับปรุงยอดการรับสินค้าเข้าคลัง (Inventory Control) ทั้งในกรณีที่เป็นการรับยอดทั่วไป และการรับยอดที่อ้างอิงจากใบสั่งซื้อ (PO) เพื่อป้องกันผลกระทบต่อข้อมูลสต๊อกคงเหลือ และเพื่อให้สามารถปิดเอกสารใบสั่งซื้อในระบบได้อย่างสมบูรณ์ โดยให้พิจารณาตามรูปแบบของเอกสารตั้งต้น ดังนี้', 'ERP Manual 14.3.68 – บทที่ 5', 'ห้ามทำการ "คืนสินค้า" (PO Return) หรือยกเลิกเอกสารรับของ (Cancel IC Receive) เด็ดขาด เพราะระบบจะไปสร้างใบลดหนี้ (Credit Note - CN) ในโมดูล AP ซึ่งจะไปกระทบกับระบบบัญชีและการตั้งหนี้ที่ได้ทำการจ่ายเงินเสร็จสิ้นไปแล้ว', '4 สิงหาคม 2569'),
  (10, 'OF', 'OF-3', 'กรณีการเปลี่ยนรูปแบบคำขอเบิกเงิน/ขออนุมัติค่าใช้จ่าย', 'Payment/Expense Request Revision', 'เพื่อป้องกันความซ้ำซ้อนในการเบิกจ่ายและการจองงบประมาณซ้ำซ้อน (Double Budgeting) ในระบบ ERP ในทุกกรณีที่มีการเปลี่ยนรูปแบบคำขอจัดซื้อจัดจ้างหรือการเบิกจ่ายเงินสด (เช่น การเปลี่ยนจาก PR เป็นเงินสดย่อย หรือสลับระหว่างเงินสดย่อย เงินทดรองจ่าย และใบเบิกเงินอื่นๆ)', 'ERP Manual 14.3.68 – บทที่ 3 (OF)', 'ห้ามดำเนินการเบิกเงินผ่านหมวดอื่นๆก่อนที่ขั้นตอนการลดยอดในหมวดเดินจะเสร็จสิ้นสมบูรณ์ เพื่อป้องกันการเบิกจ่ายซ้ำซ้อน', '1 เมษายน 2569'),
  (11, 'FA', 'FA-1', 'กรณีการโอนย้ายเครื่องจักรระหว่างโครงการ/นิติบุคคล/กิจการร่มค้า', 'Fixed Asset Transfer', 'ปัจจุบันเครื่องจักรจำนวนมากมีการระบุตำแหน่งไม่ตรงกับที่ตั้งจริง เนื่องจากเกิดความเข้าใจผิดจากการใช้ชื่อโครงการ เช่น ‘ปากท่อ–สาย 5’ ซึ่งเป็นโครงการที่ใช้สำหรับการบันทึกบัญชีในมุมมอง Profit Center เท่านั้น ทั้งนี้ตั้งแต่ปี 2569 เป็นต้นไป ให้ยกเลิกมุมมองด้าน Profit Center เพื่อให้สอดคล้องกับระบบ ERP และการทำงานของธนาคารให้มากยิ่งขึ้น โดยให้ปฏิบัติการดังขั้นตอนดังต่อไปนี้', 'ERP Manual 14.3.68 – บทที่ 9 (FA)', 'ทั้งนี้ การเปลี่ยนแปลงตำแหน่งที่ตั้งของเครื่องจักร มีผลต่อการบันทึกค่าใช้จ่ายทางบัญชี โดยค่าใช้จ่ายทั้งหมดของเครื่องจักร รวมถึง ค่าเสื่อมราคา จะถูกบันทึกและรับรู้ภายใต้งบประมาณของ โครงการที่ถูกโอนย้ายไป ดังนั้นหากไม่ต้องการให้ปรับปรุงอีกทีผ่าน GL เป็นครั้งๆ ไป', '1 เมษายน 2569'),
  (12, 'PM', 'PM-1', 'กรณีการบันทึกและประมาณการรายรับ-รายจ่ายอื่น', 'Plan Forecast Income', 'เพื่อกำหนดขั้นตอนการบันทึกวางแผนและประมาณการกระแสเงินสดรับ-จ่ายอื่น ๆ (เช่น ตั๋วสัญญาใช้เงิน, เงินกู้, ดอกเบี้ย) ผ่านฟังก์ชัน Plan Forecast Other ซึ่งเป็นโมดูลใหม่ที่พัฒนาขึ้นบนระบบ On-Web เพื่อให้การคาดการณ์สภาพคล่องทางการเงินของโครงการและแผนกมีความถูกต้อง', 'ERP Manual 14.3.68 – บทที่ 8 (PM)', '', '1 เมษายน 2569'),
  (13, 'FA', 'FA-2', 'กรณีการ Overhaul เครื่องจักรและการเพิ่มมูลค่าทรัพย์สิน', 'Machine Overhaul and Asset Value Enhancement', 'เพื่อกำหนดหลักเกณฑ์ที่ชัดเจนในการพิจารณาบันทึกรายการซ่อมบำรุงใหญ่ (Overhaul) ว่าเป็น "ค่าใช้จ่ายประจำงวด (Expense)" หรือ "การเพิ่มมูลค่าทรัพย์สิน (Capitalization)" รวมถึงกำหนดมาตรฐานการสร้างรหัสทรัพย์สิน (Asset Code) การควบคุมสิทธิ์ข้อมูล และการระบุตำแหน่งสถานที่ตั้ง (Location) ในระบบ Mango ERP (Module FA) ให้สอดคล้องกันทั้งองค์กร', 'ERP Manual 14.3.68 – บทที่ 9 (FA)', '', '1 เมษายน 2569'),
  (14, 'AP', 'AP-2', 'กรณีการระบุชื่อผู้รับเงินบนหน้าเช็ค / ใบอนุมัติจ่าย / ข้อมูลเจ้าหนี้ในระบบ', 'Beneficiary Mismatch', 'เดิมมีการจัดทำใบเตรียมจ่ายในนามบุคลากร แต่มีการออกเช็คเป็นเงินสดและแก้ไขข้อมูลบนเอกสารที่พิมพ์จากระบบภายหลัง ทำให้ระบบบันทึกเสมือนว่าได้จ่ายเงินให้แก่ผู้รับประโยชน์ตามชื่อที่ระบุแล้ว ทั้งที่ข้อเท็จจริงอาจไม่เป็นไปตามนั้น ส่งผลให้ข้อมูลทางบัญชีและข้อมูลในระบบไม่ถูกต้อง อีกทั้งผู้ที่รับเช็คไปอาจไม่นำเช็คเข้าหรือดำเนินการตามที่ตกลงไว้ จึงเพิ่มความเสี่ยงต่อความผิดพลาดและการทุจริต', 'ERP Manual 14.3.68 – บทที่ 6 (AP)', '', '1 เมษายน 2569'),
  (15, 'AP', 'AP-3', 'กรณีการตัดเจ้าหนี้ล่วงหน้าและการบันทึกใบกำกับภาษีย้อนหลัง', 'Pre-Clearing Accounts Payable and Late Tax Invoice Entry', 'ในบางกรณีแผนกการเงินจำเป็นต้องทำรายการตัดเจ้าหนี้ก่อนเพื่อให้ยอดแสดงใน Statement และส่งข้อมูลเข้าสู่ระบบ GL แต่เอกสารใบเสร็จรับเงินหรือใบกำกับภาษีตัวจริงยังมาไม่ถึง (เช่น ส่งมาทางไปรษณีย์ หรือเจ้าหนี้ออกเอกสารไม่ถูกต้อง) ทำให้ไม่สามารถแนบเอกสารเพื่อเชื่อมโยงภาษีในขั้นตอนการตัดจ่ายปกติได้ และเมื่อจัดทำงบพิสูจน์ยอดแล้วจะไม่สามารถย้อนกลับไปถอยเอกสารเพื่อแนบหลักฐานเพิ่มเติมได้ จึงจำเป็นต้องกำหนดขั้นตอนการ "บันทึกรับใบกำกับภาษีย้อนหลัง" โดยใช้อ้างอิงเลขที่เอกสาร PL เพื่อให้รายงานภาษีซื้อและข้อมูลทางบัญชีถูกต้อง รวมถึงกำหนดแนวทางการจัดเก็บเอกสารหลักฐานตัวจริงให้เป็นมาตรฐานเดียวกัน', 'ERP Manual 14.3.68 – บทที่ 6 (AP) | บทที่ 10 (GL)', '', '1 เมษายน 2569'),
  (16, 'GL', 'GL-1', 'กรณีการบันทึกขาบัญชีรายการตั๋วอาวัลและตั๋ว PN', 'Accounting Treatment for Bills of Exchange & Promissory Note', 'เดิมยังไม่มีขั้นตอนรองรับกรณีที่ ธนาคารอนุมัติออกตั๋ว การขายลดตั๋ว แก่สถาบันการเงิน และ การตัดชำระ ให้แก่ ผู้รับผลประโยชน์ตามหน้าตั๋ว ส่งผลให้ยอดระหว่างแผนกการเงินและแผนกบัญชีไม่ตรงกัน โดยเฉพาะ ในกรณีที่ไม่มีการชำระทันทีหลังจาก การขายลดตั๋ว', 'ERP Manual 14.3.68 – บทที่ 10 (GL) | บทที่ 6 (AP)', '', '1 เมษายน 2569'),
  (17, 'PM', 'PM-2', 'กรณีการบันทึกค่าซ่อมบำรุงเครื่องจักร / ค่าเช่า / Profit Centre', 'Profit Centre Bookkeeping', 'เดิมการบันทึก ค่าเช่าเครื่องจักรและค่าซ่อมบำรุงอะไหล่ของโครงการ เป็น รายได้ของสาย 5 ในมุมมองของ Profit Centre อย่างไรก็ตาม ทำให้ผลประกอบการของสาย 5  ไม่สอดคล้องกับมุมมองของธนาคาร เนื่องจากค่าใช้จ่าย อยู่ภายใต้งบประมาณของโครงการ ตาม Master Plan ที่ใช้ประกอบการขออนุมัติสินเชื่อ', 'ERP Manual 14.3.68 – บทที่ 8 (PM)', '', '1 เมษายน 2569'),
  (18, 'PM', 'PM-3', 'กรณีการวิเคราะห์และบริหารเงินในระบบ', 'Bank Account Management', 'เดิมบริษัทมีการทำรายการจ่ายเงินหรือโอนเงินระหว่างบัญชีภายในของบริษัท ทั้งกรณีที่เป็นนิติบุคคลเดียวกันและต่างนิติบุคคล โดยมิได้ระบุประเภทหรือออปชั่นการโอนเงินให้ถูกต้อง ส่งผลให้ระบบ Bank Account Management ซึ่งเป็นโมดูลที่พัฒนาเพิ่มเติมบนระบบ On-Web ไม่สามารถวิเคราะห์และจัดประเภทรายการได้อย่างถูกต้อง', 'ERP Manual 14.3.68 – บทที่ 8 (PM) | SE/FIN', '', '1 เมษายน 2569'),
  (19, 'AP', 'AP-4', 'กรณีการจ่ายเงินทดลองเพื่อเปิดวงเงินในการซื้อ-ขาย', 'Advance for Vendor Purchase Credit', 'ปัจจุบันมีความสับสนในการบันทึกเงินที่ จ่ายล่วงหน้าให้กับร้านค้า (Advance) ที่มีลักษณะคล้ายคลึงกับการวางเงินมัดจำ (Other) เนื่องจากมีการซื้อขายอย่างต่อเนื่อง และไม่มีการเปลี่ยนเช็คค้ำประกันที่ร้านค้าได้นำมาวางไว้กับบริษัท', 'ERP Manual 14.3.68 – บทที่ 6 (AP)', 'แนวทางการบันทึกและจัดการเงินจ่ายล่วงหน้า (Advance) แบบเครดิตหมุนเวียน (Rolling Credit) ตาม SOP ฉบับนี้ จะสามารถใช้ได้เฉพาะกรณีที่ร้านค้าออกใบกำกับภาษีเงินจ่ายล่วงหน้า (Advance Tax Invoice) ให้แก่บริษัทเท่านั้น', '1 เมษายน 2569'),
  (20, 'BD', 'BD-1', 'ขั้นตอนการนำเข้าและควบคุมงบประมาณ', 'Budget Import & Control', 'เพื่อกำหนดมาตรฐานการนำเข้างบประมาณ การเปิดระบบควบคุมงบประมาณและปริมาณวัสดุ (Control Budget & BOQ) รวมถึงการตั้งค่าประมาณการงบประมาณล่วงหน้า (Forecast Budget) ให้มีความถูกต้องและเชื่อมโยงข้อมูลระหว่างโมดูล BD และ PM ได้อย่างสมบูรณ์', 'ERP Manual 14.3.68 – บทที่ 2 (BD) | บทที่ 8 (PM)', '', '1 เมษายน 2569'),
  (21, 'OF', 'OF-4', 'กรณีการเคลียร์ยอดเงินทดลองและและการซ่อมทรัพย์สิน', 'Advance Balance Clearance and Asset Maintenance', 'เดิมการเคลียร์ยอดถูกดำเนินการผ่านขั้นตอนปกติที่ต้องผ่าน Loop ใบเตรียมจ่าย ส่งผลให้รายการดังกล่าวไปแสดงรวมอยู่ในรายงานค่าใช้จ่ายของโครงการซึ่งไม่ถูกต้องตามหลักการ เนื่องจากรายงานควรแสดงเฉพาะการจ่ายออกเท่านั้น ส่วนรายการเคลียร์ยอดซึ่งมีผลสุทธิเป็น 0 ไม่ควรปรากฏในรายงานดังกล่าว', 'ERP Manual 14.3.68 – บทที่ 3 (OF) | บทที่ 5 (IC)', '', '1 เมษายน 2569'),
  (22, 'SE', 'SE-1', 'กรณีการตั้งชื่อโครงการในระบบ ERP', 'Project Naming Convention', 'เดิมบริษัทมีการตั้งชื่อโครงการในลักษณะห้อยท้าย เช่น "บางเตย ตอน 1 – ศูนย์ซ่อมสาย 5" ซึ่งระบบจะตีความว่าเป็นคนละโครงการกับโครงการหลัก ส่งผลให้ค่าใช้จ่ายไม่ถูกบันทึกเข้าที่โครงการหลัก ข้อมูลใน Module: PO / WO / OF ไม่ถูกต้อง และรายงานทางบัญชีและการเงินคลาดเคลื่อน', 'ERP Manual 14.3.68 – บทที่ 1 (SE) | บทที่ 2 (BD)', '', '1 เมษายน 2569'),
  (23, 'SE', 'SE-2', 'กรณีการกำหนดผู้รับผิดชอบเปิด PR/OF และ Loop อนุมัติ', 'PR/OF Responsibility & Loop Assignment', 'เดิมการเปิด OF ทั้งหมดทำที่แผนกบัญชี และยังไม่มีการกำหนดมาตรฐานที่ชัดเจนว่าโครงการที่เกี่ยวข้องมีหน้าที่เปิด PR/OF ในแต่ละประเภทงานอย่างไร ส่งผลให้มีเปิดเอกสารผ่าน Loop หรือโครงการที่ไม่ถูกต้อง บางกรณีโครงการเปิด PR งานซ่อมบำรุงเองโดยไม่ผ่าน ศูนย์ซ่อมสาย 5 ทำให้ขาดการกำกับดูแลจากผู้จัดการศูนย์ซ่อม และข้อมูลทรัพย์สินในระบบ FA ไม่ถูกต้อง จึงจำเป็นต้องกำหนดผู้รับผิดชอบและ Loop อนุมัติสำหรับการเปิด PR และ OF แยกตามประเภทงาน ดังนี้', 'ERP Manual 14.3.68 – บทที่ 1 (SE) | บทที่ 4 (PO) | บทที่ 3 (OF)', '', '1 เมษายน 2569'),
  (24, 'OF', 'OF-5', 'กรณีการบันทึกยอดการรับเงินค่างานจากผู้ว่าจ้าง', 'Progress Submit', 'เดิมบริษัทไม่มีขั้นตอนการรับเงินและการบันทึกส่งมอบงานในระบบอย่างเป็นทางการ ทำให้เมื่อขึ้นระบบใหม่ ไม่สามารถดึงยอดรายรับตามช่องทางต่าง ๆ ไปประมวลผลในโมดูลบริหารโครงการ (PM) และโมดูลการเงิน (FIN) ได้อย่างถูกต้อง จึงกำหนดขั้นตอนการบันทึกเอกสารส่งมอบงานโครงการ (Progress Submit) สำหรับฝ่ายวิศวกรรม เพื่อใช้เป็นฐานข้อมูลรายรับที่แม่นยำในการนำไปเปิดใบแจ้งหนี้ (Invoice) ในโมดูล AR และส่งต่อข้อมูลไปประมวลผลในรายงานสถานะโครงการและกระแสเงินสด', 'ERP Manual 14.3.68 – บทที่ 3 (OF) | บทที่ 8 (PM)', '', '1 เมษายน 2569'),
  (25, 'IC', 'IC-4', 'กรณีการควบคุมสต็อกระหว่างนิติบุคคล', 'Inter-Company Stock Control', 'ในกรณีที่โครงการใช้ถังน้ำมันร่วมกัน มีความจำเป็นต้องกำหนดสัดส่วนการเบิกเข้า–เบิกออก ของแต่ละโครงการให้ชัดเจนตามปริมาณไน PO เพื่อให้สามารถควบคุมต้นทุน ตรวจสอบการใช้น้ำมัน และจัดทำรายงานได้อย่างถูกต้อง เดิมบริษัทถือว่าการจัดส่งน้ำมันไปยังจุดใด เป็นการโอนน้ำมันให้แก่โครงการนั้นทันที ซึ่งแนวปฏิบัติดังกล่าวไม่สอดคล้องกับหลักการบริหารคลังและระบบการควบคุมภายในของ ERP', 'ERP Manual 14.3.68 – บทที่ 5 (IC)', '', '1 เมษายน 2569'),
  (26, 'AP', 'AP-5', 'กรณีมีการจ่ายด่วนที่มียอดเกินจากใบเตรียมจ่ายในระบบ', 'Urgent Payments Exceeding the APP', 'มีการจ่ายเงินสดหรือออกตั๋วสัญญาใช้เงินให้แก่ร้านค้าก่อนที่จะมีการตั้งหนี้ (AP) และก่อนที่ระบบจะมีเอกสารอนุมัติจ่าย (APP) ทำให้การชำระเงินไม่สอดคล้องกับข้อเท็จจริงทางบัญชี เกิดยอดค้างชำระผิดปกติ รวมถึงส่งผลกระทบต่อกระบวนการรับสินค้าเข้าโครงการ (PO Receive / IC Receive) และทำให้ข้อมูลสต๊อกคลังสินค้าคลาดเคลื่อนจากความเป็นจริง จึงกำหนดให้การจ่ายเงินทุกประเภทต้องผ่านกระบวนการตั้งหนี้และอนุมัติจ่ายในระบบ Mango ERP อย่างเป็น Real-Time เพื่อควบคุมเงินสด/การออกตั๋วสัญญาใช้เงิน และรักษาความถูกต้องของคลังสินค้า', 'ERP Manual 14.3.68 – บทที่ 6 (AP) | บทที่ 4 (PO) | บทที่ 3 (OF)', 'แผนกบัญชีการเงินสามารถตรวจสอบรายการสั่งซื้อที่รับของแล้วแต่ยังไม่ได้ตั้งหนี้ หรือรายการขอซื้อคงค้าง ได้ผ่านรายงาน P/O Pending ในโมดูล IC', '1 เมษายน 2569'),
  (27, 'SE', 'SE-3', 'กรณีการแก้ไขสิทธิ์การใช้งานและการเพิ่มบุคลากร ในระบบ', '', 'เดิมบริษัทกำหนดสิทธิ์การใช้งานแยกตามแต่ละบริษัทเป็นจำนวนมาก ทำให้สิทธิ์ของผู้ใช้งานที่อยู่ในตำแหน่งเดียวกัน หรือลักษณะงานที่คล้ายกัน ไม่มีมาตรฐานเดียวกัน มีการเปิดและปิดสิทธิ์แตกต่างกันในแต่ละคนจนยากต่อการตรวจสอบ บริษัทจึงได้ทำการ set running number ของพนักงานทุกคนทุกกิจการให้ตรงกันและเปลี่ยนมาใช้ **Permission Template** และ **User Group** มาตรฐาน เพื่อให้สามารถกำหนดสิทธิ์ตามบทบาทหน้าที่ได้อย่างเป็นระบบ ลดความผิดพลาดในการกำหนดสิทธิ์รายบุคคล และทำให้สามารถตรวจสอบและบริหารจัดการสิทธิ์ของผู้ใช้งานให้เป็นมาตรฐานเดียวกันทั้งองค์กร', 'ERP Manual 14.3.68 – บทที่ 1', 'ห้ามแก้ไข User Rights รายบุคคล ไม่ว่าจะใน บริษัท วิจิตรภัณฑ์ ก่อสร้าง จำกัด หรือบริษัทอื่นในเครือโดยไม่ได้รับอนุมัติ หากมีความจำเป็นต้องกำหนดสิทธิที่แตกต่างจาก Template ปัจจุบัน ให้แจ้งเหตุผลว่าทำไม Template User Rights ที่ใช้อยู่จึงไม่รองรับความต้องการ และให้พิจารณาปรับปรุง Template User Rights เป็นหลัก แทนการแก้ไขสิทธิเป็นรายบุคคล เพื่อให้มาตรฐานการกำหนดสิทธิเป็นไปในแนวทางเดียวกันทั้งองค์กร', '24 กรกฎาคม 2569'),
  (28, 'FA', 'FA-3', 'แนวทางการเบิกจ่ายและบันทึกประวัติการซ่อมบำรุงเครื่องจักรระหว่างกิจการร่วมค้า (JV) และบริษัทแม่', 'Maintenance History Recording of Machinery Between the Joint Venture and Parent Company', 'เดิมการเปิดเอกสาร PR/PO สำหรับการซ่อมบำรุงเครื่องจักร ถูกดำเนินการและบันทึกในฐานข้อมูลของกิจการร่วมค้า (JV) ซึ่งเป็นคนละนิติบุคคลกับบริษัทแม่ ทำให้เกิดปัญหาประวัติการซ่อมบำรุงขาดความต่อเนื่อง และเมื่อสิ้นสุดโครงการ ประวัติของเครื่องจักรจะไม่ถูกรวมไว้ที่เดียว
INSERT INTO scenario_steps (scenario_no, step_order, kind, depth, text) VALUES
  (1, 1, 'numbered', 0, 'กรณีที่ 1: ยังไม่มีการตั้งหนี้ใดๆ ในระบบ (ยังไม่มีเอกสาร APV)'),
  (1, 2, 'caption', 0, '(แนวทาง: ทำการลดยอด PO ทันที เพื่อปิดยอดค้างรับ)'),
  (1, 3, 'sub', 1, '[แผนกจัดซื้อ/พัสดุ] ตรวจสอบประวัติการรับสินค้า (PO Receive) ของ PO ใบนั้นๆ ว่ามีการรับของไปแล้วจริงจำนวนเท่าใด มียอดค้างส่งจริงเท่าใด และทำการกดยืนยันสถานะร่วมกับแผนกวิศวกรรมหน้างานและร้านค้าคู่ค้าเพื่อเริ่มกระบวนการลดยอด'),
  (1, 4, 'sub', 1, '[แผนกจัดซื้อ] ดำเนินการลดยอดใบสั่งซื้อ (PO Decrement) เฉพาะรายการสินค้าที่ค้างส่งใน PO ใบดังกล่าว ➔ ระบุจำนวนที่ต้องการลดยอดลงในช่อง QTY Decrement ➔ ระบุเหตุผลรายละเอียดเพิ่มเติมในช่องหมายเหตุ ➔ บันทึกรายการเพื่อปิดสถานะ PO'),
  (1, 5, 'sub', 1, '[แผนกบัญชี] ไม่ต้องทำรายการปรับปรุงใดๆ ในส่วนนี้ ให้ดำเนินการตรวจสอบและบันทึกตั้งหนี้ (APV) และทำจ่ายเงินเฉพาะยอดสินค้าที่มีการรับเข้ามาจริงแล้วเท่านั้น'),
  (1, 6, 'numbered', 0, 'กรณีที่แผนกบัญชีตั้งหนี้ไป 100% และทำใบเตรียมจ่าย (Pre-Payment/APP) ไปแล้ว แต่ยังไม่ได้จ่ายเงิน'),
  (1, 7, 'caption', 0, '(แนวทาง: ถอยกระบวนการเตรียมจ่ายเพื่อปลดล็อกเอกสาร แล้วทำรายการตามกรณีที่ 1)'),
  (1, 8, 'sub', 1, '[ผู้มีอำนาจอนุมัติ] ดำเนินการยกเลิกการอนุมัติใบเตรียมจ่าย โดยเข้าไปที่ Module AP ➔ ดำเนินการ ➔ หมวดอนุมัติจ่าย ➔ เลือกเมนู ยกเลิกการอนุมัติจ่าย ➔ ระบุเหตุผลในการยกเลิกและกดปุ่มยืนยัน ➔ ส่งผลให้ชุดเตรียมจ่าย (APP) ถูกยกเลิก และเอกสารตั้งหนี้ (APV) จะถูกปลดล็อกกลับมาสู่สถานะแก้ไขได้'),
  (1, 9, 'sub', 1, '[แผนกบัญชี] เข้าไปที่เอกสาร APV ➔ กดปุ่ม Cancel Submit หรือลบเอกสาร APV นั้นออก เพื่อให้ระบบคืนยอด PO'),
  (1, 10, 'sub', 1, '[แผนกจัดซื้อ] ดำเนินการลดยอดค้างส่งตามขั้นตอนใน กรณีที่ 1 (PO Decrement) เพื่อปิดรายการที่ไม่ได้ส่งมอบให้ถูกต้อง'),
  (1, 11, 'numbered', 0, 'กรณีที่แผนกบัญชีตั้งหนี้ไป 100% และแผนกการเงินทำจ่ายเงินเรียบร้อยแล้ว'),
  (1, 12, 'caption', 0, '(แนวทาง: ทำใบลดหนี้จากยอดตั้งหนี้เดิมเพื่อเรียกเงินคืน และทำ PO Decrement ปิดงาน)'),
  (1, 13, 'sub', 1, '[แผนกบัญชี] ดำเนินการสร้างใบลดหนี้ในระบบเพื่อปรับปรุงยอด โดยเข้าไปที่ Module AP ➔ เลือกเมนู บันทึกการลดหนี้ (Credit Note) ➔ กดเลือก ลดหนี้จาก APV ➔ ค้นหาและเลือกรายการตั้งหนี้ (APV) ใบเดิมที่ทำการจ่ายเงินเกิน ➔ ระบุยอดเงินส่วนต่างที่ต้องการลดหนี้ในช่อง Amount ➔ ตรวจสอบความถูกต้องทางบัญชีเพิ่มเติมในแท็บ General Ledger, Material หรือ Tax ให้เรียบร้อยแล้วกดบันทึก (ระบบจะสร้างแบบฟอร์มใบสำคัญลดหนี้ให้โดยอัตโนมัติ)'),
  (1, 14, 'sub', 1, '[แผนกการเงิน/บัญชี] ติดต่อประสานงานกับร้านค้าคู่ค้าเพื่อติดตามเรียกคืนเงินส่วนต่างที่จ่ายเกินจริงกลับเข้าบัญชีบริษัท'),
  (1, 15, 'sub', 1, '[แผนกจัดซื้อ] ดำเนินการลดยอดใบสั่งซื้อค้างส่งตามขั้นตอนใน กรณีที่ 1 (PO Decrement) เพื่อล้างยอดและปิดสถานะ PO ในระบบให้เรียบร้อยเป็นขั้นตอนสุดท้าย'),
  (1, 16, 'numbered', 0, 'สรุปผลลัพธ์การควบคุมระบบหลังใช้งาน:'),
  (1, 17, 'sub', 1, 'จัดซื้อ (PO): ไม่มีใบสั่งซื้อคงค้างสะสม (Stale PO) ยอดงบประมาณและข้อมูลการจัดซื้อเฉลี่ยสะท้อนความเป็นจริง ไม่ส่งผลกระทบต่อความเร็วการประมวลผลรายงานของระบบ'),
  (1, 18, 'sub', 1, 'บัญชี (AP): มียอดตั้งหนี้และยอดจ่ายจริงสอดคล้องกับสินค้าที่รับเข้ามา และมีเอกสารทางภาษีควบคุมการลดหนี้ (Credit Note) ที่ถูกต้องโปร่งใส ตรวจสอบย้อนหลังได้ทุกรายการ'),
  (2, 1, 'numbered', 0, 'การควบคุมการเปิดใบสั่งซื้อเพื่อประกอบการทำตั๋วสัญญาใช้เงินอาวัล (Aval Supporting PO)'),
  (2, 2, 'sub', 1, 'กรณีเปิด PO คลุมเพื่อส่งทำตั๋วอาวัลเท่านั้น (ยังไม่มีการสั่งของจริงหน้างาน):'),
  (2, 3, 'sub', 2, '[แผนกจัดซื้อ] บันทึกเปิด PO ในระบบและสั่งพิมพ์ (Print) เอกสารใบสั่งซื้อออกมาเพื่อใช้เซ็นอนุมัตินอกระบบและส่งให้ธนาคารเป็นหลักฐานการทำตั๋วอาวัล (Aval) เท่านั้น'),
  (2, 4, 'sub', 2, '[แผนกจัดซื้อ] ต้องทำการดึงเอกสาร PO ดังกล่าวออกจากระบบทันที (Cancel/Void) เพื่อป้องกันไม่ให้มีเอกสารค้างในระบบ และห้ามส่งเอกสารชุดนี้ให้แผนกบัญชีทำการตั้งหนี้เด็ดขาด จนกว่าจะมีการสั่งซื้อและส่งมอบของจริงหน้างาน'),
  (2, 5, 'sub', 1, 'กรณีเปิด PO คลุมเพื่อสั่งซื้อจริง และร้านค้ายินยอม "ยืนราคา" (Price Lock) [แผนกบัญชี] ดำเนินการตั้งหนี้ (APV) ตามเงื่อนไขการชำระเงินดังต่อไปนี้:'),
  (2, 6, 'sub', 2, 'กรณีชำระเงินหลังส่งสินค้า (Post-payment): ให้ตั้งหนี้ (APV) อ้างอิงตามยอดในใบรับของ (PO Receive) จริงเท่านั้น'),
  (2, 7, 'sub', 2, 'กรณีชำระเงินก่อนส่งสินค้า (Pre-payment): ให้ตั้งหนี้ (APV) ตามใบแจ้งหนี้ (Invoice) และลงบันทึกบัญชีเป็น "เงินจ่ายล่วงหน้าค่าสินค้า" (Down/Advance Payment)'),
  (2, 8, 'sub', 1, 'กรณีชำระเงินก่อนส่งสินค้า และร้านค้า "ไม่ยืนราคา":'),
  (2, 9, 'sub', 2, '[แผนกจัดซื้อ] ห้ามเปิด PO คลุม แต่ให้เปิดใบสั่งซื้อ (PO) แยกตามใบขอซื้อ (PR) ทีละฉบับ'),
  (2, 10, 'sub', 2, '[แผนกจัดซื้อ] ต้องกำหนดเงื่อนไขในระบบเป็น เงินดาวน์ 100% เสมอ และพิมพ์ระบุในหมายเหตุ (Comment) บน PO ให้ชัดเจนเพื่อให้แผนกบัญชีทราบว่าต้องตั้งหนี้แบบเต็มจำนวน (Full) หรือบางส่วน (Partial)'),
  (2, 11, 'numbered', 0, 'ขั้นตอนการควบคุมและปล่อยตั๋วอาวัล (Payment Control)'),
  (2, 12, 'sub', 1, '[แผนกการเงิน] ห้ามทำการปล่อยจ่ายตั๋วออกไปให้แก่ร้านค้าเว้นแต่จะได้รับการยืนยันการเปิด PO หรือ WO ในระบบอย่างครบถ้วน และมีใบสำคัญจ่าย (Payment Voucher - PV) ในระบบเพื่อใช้ตรวจสอบเทียบยอดส่วนต่างของราคาสินค้าจริงกับยอดเงินบนหน้าตั๋วอาวัลเรียบร้อยแล้วเท่านั้น'),
  (2, 13, 'numbered', 0, 'การจัดการส่วนต่างราคาระหว่างยอดจริงกับยอดหน้าตั๋วอาวัล'),
  (2, 14, 'sub', 1, 'กรณีราคาสินค้าปรับ "ลดลง" (ยอดหน้าตั๋วอาวัลสูงกว่ามูลค่าของจริง):'),
  (2, 15, 'sub', 2, '[แผนกจัดซื้อ/การเงิน] ต้องติดต่อและแจ้งให้ร้านค้าคู่ค้าทำการตีเช็คเงินสดกลับคืนให้แก่บริษัทตามยอดส่วนต่างนั้นทันที ก่อนที่จะมีการปล่อยตั๋วสัญญาใช้เงินอาวัล (Aval) ออกไปให้ร้านค้า'),
  (2, 16, 'sub', 2, '[แผนกบัญชี] บันทึกปรับปรุงรายการ (Reverse) เพื่อล้างยอดรายการจ่ายหนี้ที่บันทึกออกไปก่อนหน้านี้ให้ถูกต้องตรงตามจริง'),
  (2, 17, 'sub', 1, 'กรณีราคาสินค้าปรับ "เพิ่มขึ้น" (ยอดหน้าตั๋วอาวัลต่ำกว่ามูลค่าของจริง):'),
  (2, 18, 'sub', 2, '[แผนกจัดซื้อ] ดำเนินการเปิดใบสั่งซื้อ (PO) ใบใหม่เพิ่มเติมเฉพาะมูลค่าส่วนต่างราคาที่ถูกต้องจริง'),
  (2, 19, 'sub', 2, '[แผนกบัญชี/การเงิน] ตั้งหนี้ (APV) และจัดทำเช็ค/โอนเงินจ่ายชำระเพิ่มเฉพาะส่วนต่างที่ขาดจากยอดหน้าตั๋วอาวัลให้แก่ร้านค้าคู่ค้าตามขั้นตอนปกติ'),
  (3, 1, 'numbered', 0, 'ในกรณีที่ยังไม่มีการรับของหรือยังรับของไม่เต็มจำนวน PO ต้นที่เปิดไว้ ให้ทำการ Revise PO เดิมทันทีเพื่อให้ไม่เกิดการคลาดเคลื่อนในจำนวนของที่รับ (PO Receive / IC Receive)'),
  (3, 2, 'sub', 1, 'ให้ไปที่ PO Module → เลือกรายการใบสั่งซื้อที่ต้องการเปลี่ยน และกด Revise'),
  (3, 3, 'sub', 1, 'เข้าไปที่รายการสินค้าที่ต้องการและกดแก้ไขราคาตามราคาปัจจุบัน ส่งอนุมัติใหม่'),
  (3, 4, 'sub', 1, 'เมื่อได้รับการอนุมัติเรียบร้อย จึงค่อยทำการรับของใหม่ในราคาและปริมาณที่ถูกต้อง'),
  (3, 5, 'numbered', 0, 'ในกรณีที่มีการรับของไปแล้ว แต่ยังไม่ได้ทำการจ่ายเงิน ให้ทำการถอยการรับของทันที โดยดำเนินการตามขั้นตอนดังต่อไปนี้'),
  (3, 6, 'sub', 1, 'ไปที่ PO Module → รับ/คืนสินค้าตามใบสั่งซื้อ (PO Receive and Return) และคลิกที่แทบคืนสินค้า (Return)'),
  (3, 7, 'sub', 1, 'เลือกรายการใบสั่งซื้อที่ต้องการทำการคืน และระบุจำนวนที่มีการรับของในราคาที่ไม่ถูกต้องในช่อง Return QTY'),
  (3, 8, 'sub', 1, 'กด Save เพื่อบันทึกการคืนของและดำเนินการต่อตามข้อที่ 1'),
  (3, 9, 'numbered', 0, 'กรณีรับของไปแล้ว และจ่ายเงินเต็มจำนวนแล้ว ต่อมามีการปรับราคา "เพิ่มขึ้น" ให้บันทึกการเพิ่มหนี้ (Debit Note) เพื่อทำจ่ายส่วนต่างและปรับปรุงมูลค่าในสต็อก (IC Cost) ให้ถูกต้อง'),
  (3, 10, 'sub', 1, '3.1 [แผนกบัญชี] เข้าไปที่ Module AP ➔ บันทึกรายการ ➔ บันทึกการเพิ่มหนี้ (Debit Note) ➔ ค้นหาและดึงรายการตั้งเจ้าหนี้ (APV) ชุดเดิมที่เคยจ่ายเงินไปแล้วขึ้นมา'),
  (3, 11, 'sub', 1, '3.2 บันทึกระบุยอดเงินส่วนต่างราคาที่เพิ่มขึ้นลงในระบบ (ระบุ Cost Code โครงงานเดิม) เพื่อเพิ่มหนี้ให้ร้านค้า ➔ ส่งต่อให้แผนกการเงินเขียนเช็ค/โอนเงินจ่ายชำระส่วนต่างเพิ่มตามปกติ (วิธีนี้จะปรับปรุงต้นทุนโครงการให้ถูกต้องทางบัญชี โดยไม่รบกวนสต๊อก)'),
  (3, 12, 'sub', 1, '3.3 [แอดมินประจำโครงการ] เข้าไปที่ Module IC ➔ Transaction ➔ Adjust Cost ➔ บันทึกปรับเพิ่มราคาทุนสินค้า (IC Cost UP) เพื่อให้ราคาทุนต่อหน่วยของสินค้าเดิมในคลังมีมูลค่าสูงขึ้นถูกต้องตรงตามยอดใบเพิ่มหนี้จริง'),
  (3, 13, 'numbered', 0, 'กรณีรับของไปแล้ว และจ่ายเงินเต็มจำนวนแล้ว ต่อมามีการปรับราคา "ลดลง" ให้ทำใบลดหนี้ (Credit Note) จากยอดเก่า และเปิด PO ใหม่สำหรับของส่วนเกินเพื่อนำมาหักลบกัน'),
  (3, 14, 'sub', 1, '4.1 การจัดการส่วนต่างราคาที่ลดลง (ทำใบลดหนี้ - Credit Note)'),
  (3, 15, 'sub', 2, '[แผนกบัญชี] เข้าไปที่ Module AP ➔ บันทึกรายการ ➔ บันทึกการลดหนี้ ➔ เลือก ลดหนี้จาก APV'),
  (3, 16, 'sub', 2, 'ค้นหาและดึงรายการตั้งเจ้าหนี้ (APV) ของยอดเดิมที่เคยจ่ายเงินเกินไปขึ้นมา'),
  (3, 17, 'sub', 2, 'ระบุยอดเงินส่วนต่างที่ต้องการปรับลดลง ตรวจสอบความถูกต้องและกด Save (ระบบจะบันทึกสร้างใบลดหนี้ CN เพื่อรอใช้หักล้าง)'),
  (3, 18, 'sub', 1, '4.2 การจัดการปริมาณสินค้าส่วนเกินที่ต้องการรับจริง (เปิด PO ใหม่โดยราคาลดลง)'),
  (3, 19, 'sub', 2, '[แผนกจัดซื้อ] เข้าไปที่ Module PO ➔ จัดทำใบสั่งซื้อ ➔ ใช้ฟังก์ชัน สำเนาเอกสาร (Copy) จาก PO ใบเดิมเพื่อความรวดเร็ว'),
  (3, 20, 'sub', 2, 'แก้ไขจำนวน (QTY) ให้เท่ากับปริมาณสินค้าส่วนที่เกินมา และแก้ไขราคาต่อหน่วย (Unit Price) ➔ ส่งอนุมัติ PO'),
  (3, 21, 'sub', 2, '[แอดมินประจำโครงการ] เมื่อ PO อนุมัติแล้ว ให้เข้าที่ Module IC เพื่อรับของส่วนเกินเข้าคลังตามปริมาณจริง'),
  (3, 22, 'sub', 1, '4.3 การตั้งหนี้และการหักกลบลบหนี้ (AP Voucher & Offset)'),
  (3, 23, 'sub', 2, '[แผนกบัญชี] ดึงเอกสารรับของจาก PO ใบใหม่ (ราคาที่ลดลงแล้ว) มาบันทึกตั้งหนี้ (AP Voucher) ตามปกติ'),
  (3, 24, 'sub', 2, '[แผนกการเงิน] ในขั้นตอนการจ่ายเงินสำหรับ PO ใบใหม่นี้ ให้ทำการดึง "ใบลดหนี้ (Credit Note)" ที่สร้างไว้ในขั้นตอนที่ 4.1 มาทำการ หักกลบลบหนี้ (Offset) กับยอดตั้งหนี้ (APV) ใบใหม่ทันที ➔ ส่งผลให้บริษัทชำระเงินจริงเพิ่มเติมเฉพาะยอดส่วนต่างสุทธิที่เหลืออยู่เท่านั้น'),
  (3, 25, 'sub', 1, '4.4 [แอดมินประจำโครงการ] ทำการปรับปรุงยอดในระบบคลังสินค้า (IC) เพื่อให้ทั้งจำนวนเงินและจำนวนของถูกต้องตรงกัน:'),
  (3, 26, 'sub', 2, 'ปรับลดต้นทุนคลังสินค้า (Adjust IC Cost): เข้าไปที่ Module IC ➔ Transaction ➔ Adjust Cost ➔ เลือกรายการวัสดุลอตเดิมที่รับไปในราคาแพง ➔ บันทึกปรับลดราคาทุนสินค้าลง (IC Cost DOWN) เพื่อให้มูลค่าสต๊อกและต้นทุนโครงการลดลงตรงตามจริง'),
  (4, 1, 'numbered', 0, 'ขั้นตอนการบันทึกใบเบิกเงินในหมวด OF ที่ถูกต้อง ผู้จัดทำเอกสารจะต้องเข้าไปที่โมดูล OF → ดำเนินการ → ใบเบิกเงินสดย่อยและใบเบิกจ่ายที่ไม่มี PO/WO ทำการเลือก "ประเภทเอกสาร" (Document Type) ให้ถูกต้องตามลักษณะรายการดังต่อไปนี้:'),
  (4, 2, 'numbered', 0, 'ประเภท Petty Cash (เบิกเงินสดย่อย) ใช้สำหรับ: ค่าใช้จ่ายเงินสดย่อยที่จ่ายไปแล้ว และต้องการตั้งเรื่องเบิกเพื่อชดเชยคืนวงเงินสดย่อย'),
  (4, 3, 'sub', 1, 'ที่ช่องประเภทเอกสาร ให้เลือก Petty Cash ระบุชื่อผู้ถือเงินสดย่อยในช่อง "จ่ายให้กับ" และเลือก โครงการ ให้ถูกต้อง'),
  (4, 4, 'sub', 1, 'เพิ่มรายการค่าใช้จ่าย (Expense Code) และตรวจสอบให้ครบถ้วนก่อนกด Save และส่งอนุมัติ'),
  (4, 5, 'numbered', 0, 'ประเภท Advance (เบิกเงินทดรองจ่าย) ใช้สำหรับ: เงินทดรองจ่ายที่บริษัทจำเป็นต้องสำรองจ่ายเงินก้อนออกไปก่อน และผู้รับเงินจะต้องนำใบเสร็จมาเคลียร์ยอดในภายหลัง'),
  (4, 6, 'sub', 1, 'ที่ช่องประเภทเอกสาร ให้เลือก Advance ระบุชื่อพนักงานที่เบิกเงินทดรองในช่อง "จ่ายให้กับ"'),
  (4, 7, 'sub', 1, 'การเลือกประเภท Advance จะทำให้ในอนาคตเมื่อนำใบเสร็จมาเคลียร์ ผู้ใช้งานจะสามารถเลือกประเภทเอกสารเป็น Clear Advance และระบบจะอนุญาตให้ดึงเอกสาร Advance เดิมมาหักล้างยอดและตัด APO ให้อัตโนมัติ'),
  (4, 8, 'sub', 1, 'หากคีย์ผิดไปเลือก "Other" ระบบจะไม่เปิดให้ดึงยอดมาหักล้าง ทำให้เกิดยอด APO ค้าง จนแผนกบัญชีต้องไปทำเอกสาร PL (สมุดรายวัน) เพื่อล้างยอดเองซึ่งผิดขั้นตอน'),
  (4, 9, 'numbered', 0, 'ประเภท Other (เบิกเงินอื่นๆ) ใช้สำหรับ: ค่าใช้จ่ายอื่น ๆ ที่มีจำนวนเงินที่ต้องจ่ายชัดเจน ไม่ต้องมีการรอเคลียร์ยอดในภายหลัง และไม่มีใบเสร็จประกอบ (เช่น ค่าธรรมเนียม, ค่าปรับ) หรือเป็นรายการที่ต้องการจ่ายเงินตรงให้กับร้านค้า/บุคคลภายนอกโดยไม่มีการทดรองจ่าย'),
  (4, 10, 'sub', 1, 'ที่ช่องประเภทเอกสาร ให้เลือก Other ที่ช่องประเภทผู้ขาย ให้เลือกเป็น External และระบุชื่อผู้รับเงินปลายทางให้ชัดเจนและกด Save เพื่อส่งอนุมัติ'),
  (4, 11, 'sub', 1, '"เงินมัดจำ" และ "เงินจ่ายล่วงหน้า / เงินดาว์น / เงินทดรองจ่าย" มีหลักการปฏิบัติในทางบัญชีและทางระบบแตกต่างกันโดยสิ้นเชิง ขอให้ฝ่ายที่เกี่ยวข้องระบุให้ชัดเจนว่าเป็นประเภทไหน เนื่องจาก OF Advance จะรองรับแค่เงินมัดจำที่ต้องได้คืนเพื่อทำการเคลียร์ยอดในระบบ'),
  (5, 1, 'numbered', 0, 'การบันทึกและเบิกชดเชยเงินสดย่อย (กรณีค่าใช้จ่ายไม่เกิน 3,000 บาท)'),
  (5, 2, 'sub', 1, '(ผู้รับผิดชอบ: แอดมินโครงการ / ผู้ถือเงินสดย่อย) ➔ เมื่อมีการจ่ายเงินสดย่อยสำหรับค่าใช้จ่ายทั่วไปในโครงการที่มูลค่าไม่เกิน 3,000 บาท ให้บันทึกคำขอชดเชยในระบบโดยเข้าที่ Module OF ➔ ดำเนินการ ➔ ใบเบิกเงินสดย่อยและใบเบิกจ่ายที่ไม่มี PO/WO'),
  (5, 3, 'sub', 1, '(ผู้รับผิดชอบ: แอดมินโครงการ / ผู้ถือเงินสดย่อย) ➔ กำหนดข้อมูลในเอกสารให้ถูกต้องดังนี้:'),
  (5, 4, 'sub', 2, 'ประเภทเอกสาร (Document Type): เลือกเป็น Petty Cash (เบิกเงินสดย่อย) เท่านั้น (ห้ามเลือกเป็น Other)'),
  (5, 5, 'sub', 2, 'รายละเอียดผู้ถือเงิน: ระบุชื่อผู้ถือเงินสดย่อย และเลือกรหัสโครงการให้ถูกต้อง'),
  (5, 6, 'sub', 2, 'แท็บรายการใบเบิกเงินสดย่อย: กดเพิ่มรายการ และเลือก "รหัสค่าใช้จ่าย" (Expense Code) ให้ตรงกับประเภทของค่าใช้จ่ายจริงแต่ละรายการ เช่น ค่าเดินทาง, ค่าน้ำดื่ม, ค่าวัสดุสิ้นเปลือง'),
  (5, 7, 'sub', 1, '(ผู้รับผิดชอบ: แอดมินโครงการ / ผู้ถือเงินสดย่อย) ➔ หากรายการใดมีภาษีมูลค่าเพิ่ม (VAT) หรือภาษีหัก ณ ที่จ่าย (WHT) ให้กรอกรายละเอียดใบกำกับภาษี/ใบเสร็จรับเงินให้ครบถ้วน พร้อมทำการ แนบไฟล์สแกนเอกสารหลักฐานการจ่ายเงินสดย่อยทุกฉบับเข้าระบบ ตรวจสอบยอดเงินสุทธิให้ถูกต้องแล้วกด Save และส่งอนุมัติเอกสารตามขั้นตอน'),
  (5, 8, 'numbered', 0, 'การตั้งหนี้และการจัดชุดทำจ่ายเงินสดย่อย (สะสมรวมยอด 3,000 บาทขึ้นไป)'),
  (5, 9, 'sub', 1, '(ผู้รับผิดชอบ: แผนกบัญชีเจ้าหนี้) ➔ การบันทึกตั้งหนี้เงินสดย่อยในระบบ (APO) ให้เข้าไปที่ Module AP ➔ ดำเนินการ ➔ ตั้งหนี้ ➔ เลือก จากการเบิกอื่นๆ (Create Voucher Other)'),
  (5, 10, 'sub', 1, '(ผู้รับผิดชอบ: แผนกบัญชีเจ้าหนี้) ➔ ดำเนินการดึงเอกสารใบเบิกเงินสดย่อยที่มีสถานะอนุมัติแล้ว (โดยเลือกดึงเฉพาะ Type: Petty Cash) ขึ้นมาตรวจสอบเอกสารแนบและความถูกต้องของรหัสบัญชี จากนั้นกดบันทึกสร้างใบสำคัญตั้งเจ้าหนี้ (APO)'),
  (5, 11, 'sub', 1, '(ผู้รับผิดชอบ: แผนกบัญชีเจ้าหนี้ / หัวหน้าแผนกบัญชี) ➔ ในการจัดทำชุดอนุมัติจ่ายเงิน (Pre-payment/APP) ให้เข้าไปที่เมนู อนุมัติจ่าย ➔ อนุมัติจ่าย APO โดยนำรายการตั้งหนี้ (APO) ของผู้ถือเงินสดย่อยรายเดียวกัน มารวบรวมเข้าด้วยกันให้ได้ยอดรวมไม่น้อยกว่า 3,000 บาท ตามนโยบายบริษัท จากนั้นระบุเลือกบัญชีธนาคารที่จะใช้จ่ายเงิน และกดบันทึกเพื่อสร้างชุดอนุมัติจ่าย (APP) จำนวน 1 ชุด'),
  (5, 12, 'sub', 1, '(ผู้รับผิดชอบ: แผนกการเงิน) ➔ ดำเนินการจ่ายชำระเงินโดยเข้าไปที่เมนู Preparing Cheque, Credit Line ➔ ชำระโดยเช็ค หรือโอนเงิน ดึงชุดอนุมัติจ่าย (APP) ดังกล่าวขึ้นมาทำจ่ายเงินให้ผู้ถือเงินสดย่อย เพื่อให้ระบบออกใบสำคัญจ่าย (Voucher PV) เพียง 1 ฉบับต่อ 1 ธุรกรรมโอนเงิน ช่วยลดความซ้ำซ้อนของเอกสาร'),
  (5, 13, 'numbered', 0, 'การจัดการเงินสดย่อยคงเหลือกรณีย้ายโครงการ (ภายในนิติบุคคลเดียวกัน)'),
  (5, 14, 'sub', 1, '(ผู้รับผิดชอบ: แผนกบัญชีทั่วไป) ➔ ในกรณีที่นายช่างหรือผู้ถือเงินสดย่อยต้องย้ายไปประจำโครงการใหม่ภายใต้นิติบุคคลเดียวกัน และต้องการโอนยอดเงินสดย่อยคงเหลือไปใช้ต่อที่โครงการใหม่ ให้ใช้วิธีโอนย้ายยอดเงินระหว่างโครงการผ่านสมุดรายวันทั่วไป โดยเข้าที่ Module GL ➔ ดำเนินการ ➔ บันทึกสมุดรายวัน (Journal Voucher) ➔ สร้างใบสำคัญ'),
  (5, 15, 'sub', 1, '(ผู้รับผิดชอบ: แผนกบัญชีทั่วไป) ➔ ทำการบันทึกรายการปรับปรุงบัญชี (JV) โยกย้ายโครงการโดยระบุรหัสบัญชีเงินสดย่อย (Account Name) และกำหนดโครงการดังนี้:'),
  (5, 16, 'sub', 2, 'ด้านเดบิต (Dr.): เลือกรหัสโครงการใหม่เพื่อรับโอนยอดเงินสดย่อยเข้าคลังโครงการใหม่'),
  (5, 17, 'sub', 2, 'ด้านเครดิต (Cr.): เลือกรหัสโครงการเดิม เพื่อปรับลดยอดเงินสดย่อยออกจากโครงการเก่า'),
  (5, 18, 'caption', 0, 'ช่องหมายเหตุ (Description): พิมพ์ระบุรายละเอียดการโอนให้ชัดเจน เช่น "โอนยอดเงินสดย่อยคงเหลือของ [ระบุชื่อพนักงาน] จากโครงการ [ระบุโครงการเดิม] ไปยังโครงการ [ระบุโครงการใหม่]" จากนั้นตรวจสอบความสมดุลของบัญชีและกด Save เพื่อบันทึกรายการ'),
  (5, 19, 'numbered', 0, 'การจัดการเงินสดย่อยคงเหลือกรณีย้ายโครงการ (ต่างนิติบุคคล)'),
  (5, 20, 'sub', 1, '(ผู้รับผิดชอบ: ผู้ถือเงินสดย่อย / พนักงาน) ➔ เนื่องจากเป็นการย้ายบุคลากรข้ามนิติบุคคลทางกฎหมาย ไม่สามารถโอนทางบัญชีตรงๆ ได้ พนักงานผู้ถือเงินสดย่อย ต้องนำเงินสดคงเหลือทั้งหมดฝากคืนเข้าบัญชีธนาคารของบริษัทเดิมให้เรียบร้อย และนำส่งใบ Pay-in หลักฐานการโอนเงินคืนให้แก่แผนกบัญชีเพื่อออกใบเสร็จรับเงิน (RV) ปิดยอดบัญชี'),
  (5, 21, 'sub', 1, '(ผู้รับผิดชอบ: แผนกบัญชีลูกหนี้) ➔ เมื่อได้รับใบนำฝากเงิน (Pay-in) จากพนักงานเรียบร้อยแล้ว ให้เข้าไปบันทึกรับเงินในระบบที่ Module AR ➔ ดำเนินการ ➔ บันทึกรับลูกหนี้อื่นๆ แบบไม่ออกใบแจ้งหนี้ (Other Receiving without Invoice)'),
  (5, 22, 'sub', 1, '(ผู้รับผิดชอบ: แผนกบัญชีลูกหนี้) ➔ บันทึกรายละเอียดการรับเงินคืนในระบบดังนี้:'),
  (5, 23, 'sub', 2, 'ประเภทรายรับ (Option Type): เลือกประเภทรายรับให้ตรงกับการคืนเงินสดย่อย'),
  (5, 24, 'sub', 2, 'Customer (ลูกค้า/ผู้จ่ายเงิน): เลือกรหัสพนักงาน/นายช่างผู้ส่งคืนเงินสดย่อย'),
  (5, 25, 'sub', 2, 'Net Amount (ยอดเงินสุทธิ): ระบุจำนวนเงินสดคงเหลือที่พนักงานโอนคืนมาตามจริง'),
  (5, 26, 'sub', 2, 'Bank A/C (บัญชีธนาคาร): ระบุบัญชีธนาคารของบริษัทที่รับโอนเงินเข้าให้ตรงตามใบ Pay-in'),
  (5, 27, 'sub', 2, 'ตรวจสอบรหัสบัญชีแยกประเภท (GL) ว่าลงบันทึกเครดิตลดบัญชีเงินสดย่อยอย่างถูกต้อง จากนั้นกด Save เพื่อสร้างใบสำคัญรับเงิน (RV) ปิดยอดคงค้างของพนักงานในนิติบุคคลเดิมอย่างสมบูรณ์'),
  (6, 1, 'numbered', 0, 'การโอนเงินภายในนิติบุคคลเดียวกัน (ทำรายการในโปรไฟล์บริษัทเดิม)'),
  (6, 2, 'sub', 1, '[ผู้ขอโอน / แผนกบริหาร] อนุมัติการโอนเงินผ่านเอกสาร Internal Memo'),
  (6, 3, 'sub', 1, 'บันทึกโอนเงินใน Module AP เลือกประเภท Check-Transfer 3 ขั้นตอน (ไม่ทำ APP) ➔ บันทึกเลขที่เช็ค (ถ้ามี) ➔ พิมพ์ Voucher PV (ใบปะหน้า) และเสนอผู้จัดการตรวจสอบลงนาม'),
  (6, 4, 'sub', 1, '[ขั้นตอนจัดการหลักฐานการโอน - แยกตามประเภทการโอน]:'),
  (6, 5, 'sub', 2, 'กรณีเช็ค TR: เขียนหรือพิมพ์เช็คสั่งจ่ายจริง ➔ เสนอลงนามและประทับตรา ➔ นำเช็คไปโอนที่ธนาคาร ➔ นำใบเสร็จโอนจริง (Pay-in/Slip) แนบประกบชุด PV กระดาษ'),
  (6, 6, 'sub', 2, 'กรณี Anywhere (ออนไลน์): โอนเงินผ่าน App ธนาคาร ➔ อัปโหลดไฟล์รูปสลิป (Digital Slip) แนบในเอกสาร PV ในระบบโดยตรง (ไม่ต้องพิมพ์สลิปกระดาษ)'),
  (6, 7, 'sub', 1, 'ดำเนินการตัดจ่ายหนี้ในระบบผ่านเมนู Clear AP'),
  (6, 8, 'numbered', 0, 'การโอนเงินระหว่างต่างนิติบุคคล (ต้องบันทึกรายการทั้งบริษัทผู้โอน และบริษัทผู้รับโอน)'),
  (6, 9, 'caption', 0, '[ฝั่งผู้โอน - บริษัท A]:'),
  (6, 10, 'sub', 1, '[ผู้ขอโอน / แผนกบริหาร] อนุมัติผ่านเอกสาร Internal Memo'),
  (6, 11, 'sub', 1, 'บันทึกโอนข้ามบริษัทใน Module AP เลือกประเภท Check-Transfer 3 ขั้นตอน (ไม่ทำ APP) ระบุคู่ค้าเป็น บริษัท B ➔ พิมพ์ Voucher PV และลงนามตรวจสอบ'),
  (6, 12, 'sub', 1, '[ขั้นตอนจัดการหลักฐานฝั่งโอน - แยกตามประเภทการโอน]:'),
  (6, 13, 'sub', 2, 'กรณีเช็ค TR: เขียน/พิมพ์เช็คสั่งจ่ายบริษัท B ➔ เสนอลงนาม ➔ นำไปโอนที่ธนาคาร ➔ แนบสลิปโอนเงินจริง (Pay-in) เข้าชุด PV บริษัท A ➔ ทำการ Clear AP'),
  (6, 14, 'sub', 2, 'กรณี Anywhere (ออนไลน์): โอนเงินผ่าน App ธนาคาร ➔ อัปโหลดไฟล์สลิป (Digital Slip) แนบในเอกสาร PV บริษัท A ในระบบ ➔ ทำการ Clear AP'),
  (6, 15, 'caption', 0, '[ฝั่งผู้รับโอน - บริษัท B]:'),
  (6, 16, 'sub', 1, 'ล็อกอินเข้าโปรไฟล์ บริษัท B ➔ บันทึกรับเงินใน Module AR เมนู >บันทึกรับลูกหนี้อื่นๆ แบบไม่ออกใบแจ้งหนี้ (Other Receiving without Invoice) ระบุผู้จ่ายเงินเป็น บริษัท A เพื่อออกใบสำคัญรับ (RV) 5. [ขั้นตอนแนบหลักฐานฝั่งรับ]:'),
  (6, 17, 'sub', 2, 'กรณีเช็ค TR: แนบใบนำฝากธนาคารจริง (Pay-in) เข้ากับชุดเอกสาร RV กระดาษ ของบริษัท B'),
  (6, 18, 'sub', 2, 'กรณี Anywhere (ออนไลน์): อัปโหลดไฟล์สลิปเดียวกัน (Digital Slip) แนบในเอกสาร RV ในระบบของบริษัท B โดยตรง'),
  (7, 1, 'numbered', 0, 'ปัจจุบันกำหนดให้ 1 โครงการ มีคลังสินค้า (Warehouse) ได้ตามจำนวนคลังสินค้าที่ตั้งอยู่จริงหน้างานเท่านั้น โดยการสร้างคลังสินค้าในแต่ละโครงการ จะต้องเริ่มต้นรหัสคลังสินค้าตำแหน่งแรกเป็นรหัส "001" เสมอ และหากมีคลังสินค้าตำแหน่งที่ 2 หรือ 3 เพิ่มเติมในโครงการเดียวกัน ให้รันรหัสต่อเนื่องเป็น "002", "003" ตามลำดับ'),
  (7, 2, 'numbered', 0, 'การตังค่า "Type of Area" เพื่อให้สะดวกต่อการเลือกใช้งานปัจจุบันบริษัทมีกำหนดแค่ฉนิดเดียวเป็น 001 "เบิกใช้งาน" เท่านั้น'),
  (7, 3, 'numbered', 0, 'การตั้งค่าข้อมูลประเภทการเบิกและสถานที่ใช้งาน "Area" ช่วยให้ฝ่ายสโตร์ทำงานได้ง่ายขึ้น และยังเป็นประโยชน์ต่อฝ่ายบริหารในการเรียกดูรายงาน (Report) ว่ามีการใช้วัสดุไปกับส่วนใด หรือด้วยสาเหตุใดมากที่สุด และปัจจุบันมีการตั้งค่าดังต่อไปนี้'),
  (7, 4, 'sub', 1, 'Area Code: 001'),
  (7, 5, 'sub', 2, 'Area Name: ใช้งาน'),
  (7, 6, 'sub', 2, 'Description: ค่าใช้จ่ายหรือรายการที่เกี่ยวข้องกับการดำเนินงานปกติ'),
  (7, 7, 'sub', 1, 'Area Code: 002'),
  (7, 8, 'sub', 2, 'Area Name: ทรัพย์สินระหว่างก่อสร้าง'),
  (7, 9, 'sub', 2, 'Description: รายการที่บันทึกเป็นสินทรัพย์ระหว่างการก่อสร้าง'),
  (7, 10, 'sub', 1, 'Area Code: 003'),
  (7, 11, 'sub', 2, 'Area Name: เบิกคิดเงิน'),
  (7, 12, 'sub', 2, 'Description: การเบิกที่สามารถเรียกเก็บหรือคิดต้นทุนกลับไปยังโครงการ/ลูกค้า'),
  (7, 13, 'sub', 1, 'Area Code: 004'),
  (7, 14, 'sub', 2, 'Area Name: เบิกไม่คิดเงิน'),
  (7, 15, 'sub', 2, 'Description: การเบิกที่ไม่เรียกเก็บหรือไม่คิดต้นทุนกลับ'),
  (7, 16, 'sub', 1, 'Area Code: 005'),
  (7, 17, 'sub', 2, 'Area Name: ปรับปรุงยอด'),
  (7, 18, 'sub', 2, 'Description: เพื่อทำการปรับปรุงยอดต่างๆ โดยสำนักงานใหญ่'),
  (8, 1, 'numbered', 0, 'การกำหนดหน่วยนับมาตรฐานจากต้นทาง (Standard Unit Definition)'),
  (8, 2, 'sub', 1, '(ผู้รับผิดชอบ: แผนกวิศวกรรม / ฝ่ายควบคุมต้นทุน) ➔ ในขั้นตอนการจัดทำและอนุมัติงบประมาณ (Budget) ในระบบ Module BD จะต้องกำหนดหน่วยนับมาตรฐานของวัสดุ (Material Code) แต่ละชนิดให้ชัดเจนตั้งแต่ต้นทาง โดยกำหนดว่าการสั่งของและการรับของเข้าสต๊อกทั้งหมดของบริษัทจะต้องใช้รหัสหน่วยนับใด เพื่อให้เป็นมาตรฐานเดียวกันทุกโครงการและทุกแผนก'),
  (8, 3, 'numbered', 0, 'การตรวจสอบหน่วยนับในกระบวนการขอซื้อและสั่งซื้อ (PR/PO Unit Verification)'),
  (8, 4, 'sub', 1, '(ผู้รับผิดชอบ: ผู้ขอเบิก / แอดมินประจำโครงการ) ➔ ในการจัดทำใบขอซื้อ (PR) หน้างานจะต้องตรวจสอบและระบุหน่วยนับของวัสดุให้ตรงกับหน่วยการรับสินค้า (PO Receive) และการรับเข้าคลัง (IC Receive) ตามที่ผูกไว้ในฐานข้อมูลระบบ ERP เท่านั้น เพื่อป้องกันปัญหาการแปลงหน่วยย้อนหลังซึ่งอาจทำให้เกิดเศษทศนิยมคลาดเคลื่อนในคลังสินค้า'),
  (8, 5, 'sub', 1, '(ผู้รับผิดชอบ: ฝ่ายจัดซื้อ) ➔ ก่อนอนุมัติออกใบสั่งซื้อ (PO) ให้ดำเนินการตรวจสอบหน่วยนับของรายการสินค้าอีกครั้ง หากพบว่าร้านค้าเสนอราคาในหน่วยที่แตกต่างจากหน่วยมาตรฐานของบริษัท ฝ่ายจัดซื้อจะต้องคำนวณปริมาณและราคาเพื่อเปิด PO ให้เป็นหน่วยมาตรฐานของบริษัทเสมอ'),
  (8, 6, 'sub', 1, 'ตัวอย่างกระบวนการ: หากจัดซื้อต้องการบันทึกข้อมูลอ้างอิงของร้านค้าเพิ่มเติม สามารถพิมพ์ระบุน้ำหนักรวมหรือรายละเอียดหน่วยที่ร้านค้าเสนอมาในช่องหมายเหตุ (Remark) หรือฟังก์ชัน Note แทนได้ เพื่อใช้เป็นหลักฐานอ้างอิงตอนตรวจรับของ'),
  (8, 7, 'numbered', 0, 'มาตรฐานหน่วยนับสำหรับกลุ่มวัสดุหลัก (Standard Material Unit Specifications)'),
  (8, 8, 'sub', 1, '(ผู้รับผิดชอบ: ฝ่ายจัดซื้อ และ แอดมินประจำโครงการ) ➔ เพื่อความเป็นเอกภาพของระบบข้อมูล ให้ทุกฝ่ายที่เกี่ยวข้องยึดถือมาตรฐานหน่วยนับสำหรับวัสดุหลักของบริษัท ดังต่อไปนี้:'),
  (8, 9, 'sub', 1, 'กลุ่มวัสดุเหล็ก: ให้จัดทำเอกสาร PR/PO และทำรับของโดยระบุหน่วยนับเป็น "เส้น" เท่านั้น'),
  (8, 10, 'sub', 1, 'กลุ่มวัสดุหิน / ดิน / ทราย / ปูน  ให้จัดทำเอกสาร PR/PO โดยระบุหน่วยนับเป็น "ตัน" เท่านั้น โดยเมื่อแอดมินโครงการทำรับของเข้าคลัง (IC Receive) ระบบจะทำการแปลงหน่วย (Convert) เป็นหน่วย "กิโลกรัม" ให้โดยอัตโนมัติในระบบคลังสินค้า'),
  (9, 1, 'numbered', 0, 'การรับวัสดุกลับเข้าคลัง (กรณีเบิกของ หรือ โอนของผิดพลาด)'),
  (9, 2, 'caption', 0, '(ผู้รับผิดชอบ: แอดมินประจำโครงการ / พัสดุกลาง)'),
  (9, 3, 'sub', 1, 'กรณีทำการ "เบิกของผิด" (Return From Issue)'),
  (9, 4, 'sub', 2, 'เข้าเมนู Module IC → Transaction → Document IC Receive → เลือกเมนู Stock Receive (รับวัสดุเข้าคลัง)'),
  (9, 5, 'sub', 2, 'ที่ช่อง Type ให้เลือกเป็น "Return From Issue"'),
  (9, 6, 'sub', 2, 'การดึงข้อมูล: กดค้นหาและเลือกเอกสารใบเบิกของ (IC Issue) ใบเดิมที่เบิกผิดออกไป'),
  (9, 7, 'sub', 2, 'การปรับยอด: ระบุ Document Date ให้เป็นวันที่เดียวกับที่เบิกผิด และใส่เหตุผลในช่อง Remark'),
  (9, 8, 'sub', 2, 'จากนั้นไปที่แท็บ Material Receive แล้วระบุปริมาณที่ต้องการรับกลับเข้าคลังในช่อง QTY (IC)'),
  (9, 9, 'sub', 2, 'ตรวจสอบคลังสินค้า (Warehouse) ให้ถูกต้อง แล้วกด Save'),
  (9, 10, 'sub', 1, 'กรณีทำการ "โอนของผิด" (Return From Transfer)'),
  (9, 11, 'sub', 2, 'เข้าเมนูเดียวกัน เลือก Stock Receive'),
  (9, 12, 'sub', 2, 'ที่ช่อง Type ให้เลือกเป็น "Return From Transfer"'),
  (9, 13, 'sub', 2, 'การดึงข้อมูล: กดค้นหาและเลือกเอกสารใบโอนของ (IC Transfer) ใบเดิมที่โอนออกไปผิด'),
  (9, 14, 'sub', 2, 'การปรับยอด: ระบุวันที่และหมายเหตุเช่นเดียวกัน จากนั้นระบุปริมาณในช่อง QTY (IC) และกด Save เพื่อรับของกลับเข้าคลังตั้งต้น'),
  (9, 15, 'numbered', 0, 'การลดยอดสต๊อก หรือ ตัดสินค้าคืนร้านค้า (กรณีรับของจาก PO ผิดพลาด)'),
  (9, 16, 'caption', 0, '(ผู้รับผิดชอบ: แอดมินประจำโครงการ / พัสดุกลาง)'),
  (9, 17, 'sub', 1, 'หากตรวจรับสินค้าเข้าคลังผ่านใบสั่งซื้อ (PO) ไปแล้ว แต่พบว่าสินค้าไม่ตรงสเปก ชำรุด หรือจำนวนเกิน และต้องการส่งคืนร้านค้าเพื่อลดยอดสต๊อกและยอดตั้งหนี้'),
  (9, 18, 'sub', 2, 'เข้าเมนู Module IC → Transaction → Document IC Receive → เลือกเมนู P/O Receive (รับ/คืนสินค้า)'),
  (9, 19, 'sub', 2, 'ค้นหาใบ PO ที่ต้องการคืนสินค้า แล้วเลือกรายการวัสดุที่ต้องการรับคืน'),
  (9, 20, 'sub', 2, 'การปรับยอด: ใส่หมายเหตุในช่อง "ส่งคืนหมายเหตุ" จากนั้นไปที่แท็บ รายการสินค้า และระบุจำนวนที่ต้องการลดยอดส่งคืนลงในช่อง Return QTY (หรือกดรับคืนทั้งหมด) แล้วกด Save ระบบจะสร้างใบคืนสินค้าและลดยอดสต๊อกให้ทันที'),
  (9, 21, 'numbered', 0, 'การปรับลดยอดสต๊อกทั่วไป หรือ การย้ายคลังสินค้า'),
  (9, 22, 'caption', 0, '(ผู้รับผิดชอบ: แผนกพัสดุกลาง)'),
  (9, 23, 'sub', 1, 'กรณีต้องการตัดของทิ้ง / ลดยอดทั่วไป (Stock Issue)'),
  (9, 24, 'sub', 2, 'เข้าเมนู Module IC → Transaction → Document IC Issue → Entry Document'),
  (9, 25, 'sub', 2, 'เลือกประเภทเอกสารเป็น "Issue" ระบุรายละเอียด และเลือก Material ที่ต้องการลดยอด พร้อมใส่ปริมาณลงในช่อง QTY'),
  (9, 26, 'sub', 2, 'ระบุ Area Code เป็น 0005 "ปรับปรุงยอด"  และระบุหมายเหตุ (Remark) เช่น "ปรับปรุงลดยอดสต๊อกเนื่องจาก คีย์ข้อมูลผิดพลาด"'),
  (9, 27, 'sub', 2, 'เลือก Material รหัสที่รับเข้ามาผิด และระบุปริมาณ (QTY) ที่ต้องการลดยอดออก'),
  (9, 28, 'sub', 2, 'เมื่อสร้างใบเตรียมเบิกเสร็จสิ้น ให้ไปที่เมนู Stock Issue (เอกสารเบิกวัสดุ) ดึงเอกสารใบเตรียมเบิกดังกล่าวมากด Save เพื่อตัดยอดวัสดุที่ผิดออกจากคลังอย่างสมบูรณ์'),
  (9, 29, 'sub', 1, 'กรณีที่ต้องการบันทึกรหัสสินค้าใหม่ที่ถูกต้องเข้าไปในคลังเพื่อทดแทนรหัสเดิม'),
  (9, 30, 'sub', 2, 'เข้าไปที่ Module IC → Transaction → Document IC Receive → Stock Receive (รับวัสดุเข้าคลัง)'),
  (9, 31, 'sub', 2, 'เลือกช่อง Type เป็น Other และ ระบุในช่องหมายเหตุ (Remark) ว่า "รับเข้าเพื่อปรับปรุงยอดจากการคีย์ข้อมูลผิดพลาด"'),
  (9, 32, 'sub', 2, 'ไปที่แท็บ Material Receive กดแก้ไขแล้วระบุคลังสินค้า (Warehouse) พร้อมด้วยรหัสวัสดุและปริมาณที่ถูกต้อง (ไม่ต้องกรอก QTY PO / Amount PO)'),
  (9, 33, 'sub', 2, 'ตรวจสอบความถูกต้องแล้วกด Save'),
  (9, 34, 'sub', 1, 'กรณีต้องการสลับคลัง หรือ โอนย้ายข้ามโครงการ (Stock Transfer)'),
  (9, 35, 'sub', 2, 'ขั้นตอนเตรียมโอน: เข้าเมนูเดียวกับด้านบน แต่เลือกประเภทเอกสารเป็น "Transfer"'),
  (9, 36, 'sub', 2, 'การตั้งค่า: ระบุโครงการปลายทางในช่อง To Project จากนั้นเลือก Material และใส่ปริมาณ (QTY) ที่ต้องการย้าย'),
  (9, 37, 'sub', 2, 'ขั้นตอนตัดและรับโอน: โครงการต้นทางดึงเอกสารไปทำ Transfer (เอกสารโอนวัสดุ) เพื่อตัดยอดออก และโครงการปลายทางต้องไปทำ Receive (เอกสารรับโอนวัสดุ) เพื่อรับยอดเข้าคลังใหม่'),
  (9, 38, 'numbered', 0, 'การปรับปรุง "ต้นทุน" ของวัสดุในคลัง (โดยไม่กระทบปริมาณ)'),
  (9, 39, 'caption', 0, '(ผู้รับผิดชอบ: แผนกพัสดุกลาง)'),
  (9, 40, 'sub', 1, 'หากจำนวน QTY ของวัสดุในคลังถูกต้องแล้ว แต่มีค่าใช้จ่ายเพิ่มเติม (เช่น ค่าขนส่งนำเข้า หรือค่าใช้จ่ายจากเงินสดย่อย) ที่ต้องการนำมาบวกเฉลี่ยเพิ่มเป็น "ต้นทุนต่อหน่วย" ของสินค้านั้นๆ'),
  (9, 41, 'sub', 2, 'ขั้นตอน: เข้าเมนู Module IC → Transaction → Enter Cost Material Other'),
  (9, 42, 'sub', 2, 'การตั้งค่า: เลือก Average by Amount เพื่อให้ระบบถัวเฉลี่ยต้นทุน'),
  (9, 43, 'sub', 2, 'การดึงข้อมูล: ดึงเอกสารใบตั้งหนี้ค่าใช้จ่าย (APO) ที่ต้องการนำมาเป็นต้นทุน ตรวจสอบรายการในแท็บ Material Cost Other แล้วกด Save ต้นทุนดังกล่าวจะถูกปันส่วนเข้ามูลค่าสินค้าในคลังโดยอัตโนมัติ'),
  (10, 1, 'numbered', 0, 'การยกเลิกเอกสารคำขอเดิมก่อนการเปลี่ยนรูปแบบ (Cancellation of the Prior Request)'),
  (10, 2, 'caption', 0, 'ข้อกำหนดทั่วไป: ไม่ว่าจะเป็นการเปลี่ยนรูปแบบจากช่องทางใดก็ตาม ห้าม ดำเนินการเปิดเอกสารคำขอใหม่ในระบบหากยังไม่ได้ทำการยกเลิกหรือลดยอดเอกสารคำขอเดิมที่ค้างอยู่ในระบบให้เรียบร้อยก่อน โดยแบ่งเป็นกรณีดังนี้:'),
  (10, 3, 'sub', 1, 'กรณีที่ 1.1: เปลี่ยนรูปแบบจาก "ใบขอซื้อ (PR)" ➔ "ใบเบิกเงินสด (OF)" (ผู้รับผิดชอบ: ผู้ขอเบิก / แอดมินประจำโครงการ)'),
  (10, 4, 'sub', 2, 'เข้าสู่ระบบงานสำนักงาน Module OF ➔ ดำเนินการ ➔ บันทึกใบขอซื้อ ➔ เลือกเมนู "ลดยอดรายการขอซื้อ"'),
  (10, 5, 'sub', 2, 'ค้นหาเอกสารใบขอซื้อ (PR) ใบเดิม และเลือกรายการวัสดุที่ต้องการยกเลิก'),
  (10, 6, 'sub', 2, 'ในช่อง QTY Decrement ให้ระบุจำนวนที่ต้องการยกเลิก และระบุสาเหตุในช่องหมายเหตุ เช่น "ร้านค้าไม่เสนอราคา ขอเปลี่ยนรูปแบบไปเบิกเงินทดรองจ่ายแทน"'),
  (10, 7, 'sub', 2, 'ตรวจสอบข้อมูลและกดปุ่ม Save เพื่อคืนงบประมาณ (Budget) กลับเข้าโครงการ'),
  (10, 8, 'sub', 1, 'กรณีที่ 1.2: เปลี่ยนรูปแบบระหว่างเอกสารเบิกเงินสดด้วยกัน "OF" ➔ "OF" เช่น เงินสดย่อย (Petty Cash) ➔ เงินทดรองจ่าย (Advance) หรือ ใบเบิกเงินอื่นๆ (Other) (ผู้รับผิดชอบ: ผู้ขอเบิก / แอดมินประจำโครงการ)'),
  (10, 9, 'sub', 2, 'เข้าไปที่เมนูบันทึกรายการของเอกสารเดิมที่เคยสร้างไว้ (เช่น หากเดิมทำเป็นใบเบิกเงินสดย่อย ให้เข้าเมนูบันทึกเงินสดย่อย)'),
  (10, 10, 'sub', 2, 'ค้นหาเลขที่เอกสารใบเดิมที่มีความประสงค์จะยกเลิก'),
  (10, 11, 'sub', 2, 'ดำเนินการกดปุ่ม "ยกเลิกเอกสาร (Cancel / Void)" ในระบบเพื่อปลดล็อกยอดเงินงบประมาณที่ถูกจองไว้ให้กลับคืนสู่โครงการ'),
  (10, 12, 'numbered', 0, 'การตั้งคำขอเบิกเงินในรูปแบบใหม่ทดแทน (Creation of the New Request) (ผู้รับผิดชอบ: ผู้ขอเบิก / แอดมินประจำโครงการ)'),
  (10, 13, 'sub', 1, 'เข้าสู่ระบบงานสำนักงาน Module OF ➔ ดำเนินการ ➔ เลือกเมนู "ใบเบิกเงินสดย่อยและใบเบิกจ่ายที่ไม่มี PO/WO"'),
  (10, 14, 'sub', 1, 'เลือกประเภทเอกสารในรูปแบบใหม่ที่ต้องการสลับใช้อย่างเหมาะสม:'),
  (10, 15, 'caption', 0, 'Petty Cash (เงินสดย่อย): สำหรับการจ่ายเงินสดมูลค่าไม่สูงหน้างาน'),
  (10, 16, 'caption', 0, 'Advance (เบิกเงินทดรองจ่าย): สำหรับกรณีขอเบิกเงินก้อนล่วงหน้าไปสำรองจ่ายให้ร้านค้าก่อน'),
  (10, 17, 'caption', 0, 'Other (เบิกเงินอื่นๆ): สำหรับกรณีที่ต้องการให้ฝ่ายการเงินสำนักงานใหญ่โอนเงินชำระตรงให้ร้านค้าภายนอก'),
  (10, 18, 'sub', 1, 'ระบุโครงการ รหัสแผนก และผู้ขอเบิกให้ถูกต้อง'),
  (10, 19, 'sub', 1, 'ในช่องรายละเอียดหรือคำอธิบายเหตุผลของการเบิกใบใหม่ ต้องระบุข้อความเชื่อมโยงถึงเอกสารเดิมที่ยกเลิกไปเสมอ เพื่อความโปร่งใสและเป็นหลักฐานอ้างอิงในการตรวจสอบย้อนหลัง เช่น "เบิกเพื่อซื้อวัสดุทดแทน [ระบุประเภทเดิม เช่น PR หรือ เงินสดย่อย] เลขที่ [ระบุเลขเอกสารเดิม] ที่ได้ทำการยกเลิกในระบบแล้ว"'),
  (10, 20, 'sub', 1, 'บันทึกระบุรหัสต้นทุน (Cost Code) และยอดเงินให้เรียบร้อย ตรวจสอบความถูกต้องและกดปุ่ม Save เพื่อส่งอนุมัติ'),
  (11, 1, 'numbered', 0, 'การขออนุมัติโอนย้าย (Transfer Request & Approval)'),
  (11, 2, 'sub', 1, 'ผู้โอน: จัดทำเอกสารขอโอนย้ายในระบบ พร้อมแนบเอกสารประกอบที่เกี่ยวข้อง (เช่น ใบประเมินสภาพทรัพย์สิน/ประเมินมูลค่า) เพื่อแจ้งให้โครงการ/แผนกผู้รับทราบล่วงหน้า และให้ผู้รับสามารถตรวจสอบข้อมูลทรัพย์สินรวมถึงสภาพเครื่องจักรได้ครบถ้วนก่อนการโอนย้ายจริง'),
  (11, 3, 'numbered', 0, 'การบันทึกเอกสารโอนย้ายในระบบ ERP (Asset Transfer Execution)'),
  (11, 4, 'sub', 1, 'ผู้โอน: เมื่อเอกสารขอโอนย้ายได้รับการอนุมัติเรียบร้อยแล้ว ให้เข้าไปดำเนินการโอนย้ายทรัพย์สินในระบบ Mango ERP ดังนี้:'),
  (11, 5, 'sub', 1, 'เข้าสู่โมดูล FA (Fixed Asset) → เลือก โอนย้ายทรัพย์สิน → กด "สร้างเอกสารโอนย้าย" (Transfer Asset Document)'),
  (11, 6, 'sub', 1, 'ระบุ วันที่เอกสาร (Date), ประเภทการโอน (โครงการ/แผนก) และเลือก โครงการ/แผนกปลายทาง (To Project )'),
  (11, 7, 'sub', 1, 'กดดึงรายการทรัพย์สิน/เครื่องจักรที่ต้องการโอนย้ายเข้ามาในเอกสาร ระบุข้อมูลสำคัญให้ครบถ้วน:'),
  (11, 8, 'sub', 1, 'Employee Code: ระบุรหัสผู้ถือครอง/ผู้รับผิดชอบใหม่ปลายทาง'),
  (11, 9, 'sub', 1, 'Location Code / Sub Location Code: ระบุตำแหน่งที่ตั้งปลายทาง'),
  (11, 10, 'sub', 1, 'ข้อมูลการขนส่ง: ระบุชื่อคนขับรถ (Driver), ทะเบียนรถ (Vehicle Registration) และผู้จัดส่ง (Transported by)'),
  (11, 11, 'sub', 1, 'ตรวจสอบความถูกต้อง แล้วกด Save (บันทึก) เพื่อให้ระบบสร้างแบบฟอร์ม "ใบโอนย้ายทรัพย์สิน"'),
  (11, 12, 'numbered', 0, 'การจัดส่งพร้อมเอกสารหลักฐาน (Physical Transport)'),
  (11, 13, 'sub', 1, 'ผู้โอน: พิมพ์เอกสาร "ใบโอนย้ายทรัพย์สิน" จากระบบ ERP และจัดส่งเอกสารฉบับจริงแนบไปพร้อมกับการขนย้ายตัวเครื่องจักรหรือทรัพย์สิน เพื่อใช้เป็นหลักฐานกำกับตัวสินค้าและใช้ตรวจรับมอบ ณ สถานที่ปลายทาง'),
  (11, 14, 'numbered', 0, 'การตรวจรับมอบและยืนยันในระบบ (Receipt & Verification)'),
  (11, 15, 'sub', 1, 'ผู้รับ: เมื่อเครื่องจักรถึงสถานที่ปลายทาง ให้ผู้รับทำการตรวจสอบความถูกต้องและสภาพเครื่องจักรจริง แล้วทำการ ลงนามรับมอบ ในเอกสาร "ใบโอนย้ายทรัพย์สิน" ฉบับจริงเพื่อเป็นหลักฐาน'),
  (11, 16, 'sub', 1, 'ผู้รับ / เจ้าหน้าที่ระบบ: เข้าไปที่โมดูล FA → เลือก "ตรวจสอบทรัพย์สินโอนย้าย" เพื่ออัปเดตและยืนยันสถานะที่ตั้งของทรัพย์สินในระบบให้ตรงตามจริง'),
  (11, 17, 'numbered', 0, 'หลักเกณฑ์การระบุตำแหน่งที่ตั้งของเครื่องจักร (Location Guidelines)'),
  (11, 18, 'sub', 1, 'การโอนย้ายทุกครั้ง ต้องระบุรหัสสถานที่ตั้ง (Location / Sub Location) ให้ตรงกับจุดที่เครื่องจักรนั้นตั้งอยู่จริง ณ ขณะนั้น ตัวอย่าง: หากเครื่องจักรถูกส่งไปซ่อมบำรุงที่โครงการ ศูนย์ซ่อมสาย 5 ให้ระบุ Location เป็น "ศูนย์ซ่อมเครื่องจักรกล พุทธมณฑลสาย 5" แต่เมื่อซ่อมเสร็จและย้ายไปที่โครงการ ปากท่อ ให้ทำเอกสารโอนย้ายในระบบอีกครั้งเพื่อปรับเปลี่ยน Location เป็น "โครงการปากท่อ ตอน 2" ให้ตรงตามข้อเท็จจริง'),
  (11, 19, 'sub', 1, 'ในกรณีจำเป็นที่ตัวเครื่องจักรจริงยังไม่สามารถเคลื่อนย้ายไปยังสถานที่ใหม่ได้ แต่จำเป็นต้องโอนย้ายทางระบบ ERP เพื่อให้ต้นทุนไปลงยังโครงการใหม่ เนื่องจากโครงการเดิมปิดหรือสิ้นสุดลงแล้ว ให้ทำการโอนย้ายระบุโครงการปลายทาง (To Project) เป็นโครงการใหม่เพื่อรับรู้ต้นทุน แต่ในช่อง Location / Sub Location หรือ Remark (หมายเหตุ) ให้ระบุสถานที่ที่เครื่องจักรวางอยู่จริง ณ ขณะนั้นอย่างชัดเจน เพื่อให้แผนกบัญชีและสโตร์/ช่างซ่อมบำรุงสามารถติดตามตำแหน่งกายภาพของเครื่องจักรได้ถูกต้อง'),
  (11, 20, 'numbered', 0, 'ในกรณีโอนย้ายทรัพย์สินเข้าโครงการจำลอง (Dummy Project) ของกิจการร่วมค้าภายในระบบบริษัทแม่'),
  (11, 21, 'sub', 1, 'แทนที่จะทำการตัดจำหน่ายเพื่อขาย (Sold) ข้ามฐานข้อมูลบริษัท ให้ใช้วิธี สร้างรหัสโครงการจำลอง (Dummy Project) ที่เป็นตัวแทนของไซต์งาน JV นั้นๆ ขึ้นมาใน "ฐานข้อมูลของบริษัทแม่" จากนั้นใช้เมนูโอนย้ายทรัพย์สิน (Asset Transfer) ภายในระบบบริษัทแม่ตามปกติ วิธีนี้จะทำให้:'),
  (11, 22, 'sub', 1, 'กรรมสิทธิ์และประวัติการซ่อมบำรุงเครื่องจักรยังคงอยู่กับบริษัทแม่ 100%'),
  (11, 23, 'sub', 1, 'บริษัทแม่สามารถติดตามตำแหน่งที่ตั้ง (Location) และโครงการที่เครื่องจักรไปปฏิบัติงานได้แบบ Real-time'),
  (11, 24, 'sub', 1, 'ค่าเสื่อมราคา (Depreciation) จะถูกบันทึกแยกเป็นต้นทุนของโครงการจำลองนั้นๆ อย่างชัดเจน จากนั้นให้แผนกบัญชีทำการดึงข้อมูลไปปิดงบรวม และทำการเรียกเก็บค่าเช่าที่บริษัทแม่ที่เดียว'),
  (12, 1, 'numbered', 0, 'ข้อกำหนดและนโยบายการควบคุม:'),
  (12, 2, 'sub', 1, 'การปิดรายการเมื่อเกิดขึ้นจริง (Closing Rule): เมื่อรายการรับหรือจ่ายเงินตามที่ประมาณการไว้ "เกิดขึ้นจริงแล้ว" ผู้บันทึกจะต้องเข้าไปเปลี่ยนสถานะเอกสารเป็น "Close" เสมอ เพื่อป้องกันไม่ให้ระบบยกยอดประมาณการดังกล่าวไปคำนวณซ้ำในเดือนถัดไป'),
  (12, 3, 'sub', 1, 'การควบคุมความคลาดเคลื่อน (Variance Control): ผู้บันทึกต้องกลับไปตรวจสอบความถูกต้องของรายการทุกครั้ง หากพบว่ามูลค่าที่เกิดขึ้นจริง มีความคลาดเคลื่อนจากยอดประมาณการ เกินกว่า 10% (ไม่ว่าจะสูงกว่าหรือต่ำกว่า) จะต้องแจ้งให้โครงการหรือแผนกที่เกี่ยวข้องทราบทันทีเพื่อปรับแผนดำเนินงาน'),
  (12, 4, 'numbered', 0, 'ขั้นตอนการปฏิบัติงานในระบบ Mango ERP (System Workflow)'),
  (12, 5, 'sub', 1, 'ขั้นตอนที่ 1: การบันทึกสร้างประมาณการ (Create Plan Forecast Other)'),
  (12, 6, 'caption', 0, '(ผู้รับผิดชอบ: ผู้บันทึกประมาณการ / ฝ่ายการเงินหรือบัญชี)'),
  (12, 7, 'sub', 1, 'เข้าสู่โมดูล PM → เมนู Project Forecast → เลือก Plan Forecast Other'),
  (12, 8, 'caption', 0, 'ระบุข้อมูลรายละเอียดของรายการให้ครบถ้วน ดังนี้:'),
  (12, 9, 'sub', 2, 'Document Type: ระบุประเภทรายการให้ชัดเจนว่าเป็น Income (รายรับ) หรือ Expense (รายจ่าย)'),
  (12, 10, 'sub', 2, 'Option: ระบุประเภทของค่าใช้จ่ายหรือรายได้ให้ตรงตามวัตถุประสงค์ เช่น Promissory Note (ตั๋วสัญญาใช้เงิน), Loan (เงินกู้ยืม), Interest (ดอกเบี้ย) หรืออื่น ๆ'),
  (12, 11, 'sub', 2, 'Bank: ระบุว่ารายการรับ-จ่ายนี้ จะทำธุรกรรมผ่านเข้า/ออกบัญชีธนาคารใด'),
  (12, 12, 'sub', 2, 'Project / Department: ระบุว่ารายการนี้เป็นการทำรายการเข้าโครงการใด หรือรับผิดชอบโดยแผนกใด'),
  (12, 13, 'sub', 2, 'ตรวจสอบข้อมูล ยอดเงินประมาณการ และกดบันทึกข้อมูลในระบบ'),
  (12, 14, 'sub', 1, 'ขั้นตอนที่ 2: การติดตามและอัปเดตสถานะ (Follow-up & Close Status)'),
  (12, 15, 'caption', 0, '(ผู้รับผิดชอบ: ผู้บันทึกประมาณการ)'),
  (12, 16, 'sub', 1, 'การปิดรายการ (Close): เมื่อได้รับเงินหรือจ่ายเงินจริงเรียบร้อยแล้ว ให้ผู้บันทึกกลับเข้ามาที่รายการเดิม แล้วทำการเปลี่ยนสถานะรายการเป็น "Close" ทันที'),
  (12, 17, 'sub', 1, 'การแจ้งเตือนความคลาดเคลื่อน (Variance Alert): ตรวจสอบยอดเงินที่เกิดขึ้นจริงเทียบกับที่ประมาณการไว้ หากคำนวณแล้วพบว่าคลาดเคลื่อนเกิน 10% ให้ดำเนินการทำสรุปแจ้งโครงการหรือผู้เกี่ยวข้องรับทราบเพื่อหาแนวทางบริหารจัดการต่อไป'),
  (13, 1, 'numbered', 0, 'หลักเกณฑ์การพิจารณาทางบัญชี (Capitalization vs. Expense Policy)'),
  (13, 2, 'sub', 1, 'ดุลพินิจและการอนุมัติ: การตัดสินใจว่าจะบันทึกเป็นค่าใช้จ่าย หรือ นำไปบันทึกเพิ่มมูลค่าทรัพย์สิน ให้ถือเป็น ดุลพินิจและอำนาจการพิจารณาของแผนกบัญชีและฝ่ายบริหาร เท่านั้น'),
  (13, 3, 'sub', 1, 'เกณฑ์มูลค่าขั้นต่ำ (Threshold): รายการที่จะพิจารณา Overhaul เป็นการเพิ่มมูลค่าทรัพย์สิน ต้องมีมูลค่าการซ่อมบำรุง มากกว่า [xxx] บาท/ล้านบาท ขึ้นไป (หากมูลค่าต่ำกว่าเกณฑ์ ให้บันทึกเป็นค่าใช้จ่ายซ่อมแซมประจำงวดในหมวด OF/AP)'),
  (13, 4, 'sub', 1, 'เกณฑ์เพิ่มประสิทธิภาพ/อายุการใช้งาน: การ Overhaul นั้นต้องส่งผลให้อายุการใช้งานของเครื่องจักรยาวนานขึ้น หรือเพิ่มประสิทธิภาพการทำงานอย่างมีนัยสำคัญ'),
  (13, 5, 'numbered', 0, 'การควบคุมสิทธิ์การแก้ไขข้อมูล (Security & Permission Control)'),
  (13, 6, 'sub', 1, 'สิทธิ์การแก้ไข Serial No.: จำกัดสิทธิ์ในการแก้ไข/ปรับปรุงข้อมูลเลขซีเรียล (Serial No.) ของทรัพย์สิน เฉพาะพนักงานแผนกบัญชีทรัพย์สินที่ได้รับมอบหมายอย่างเป็นทางการเท่านั้น (กำหนดสิทธิ์ผ่าน Module SE / User Management) เพื่อป้องกันการแก้ไขข้อมูลโดยไม่ได้รับอนุญาต'),
  (13, 7, 'numbered', 0, 'การตั้งรหัสทรัพย์สินและการลงทะเบียน (Asset Code Naming Convention)'),
  (13, 8, 'sub', 1, 'รูปแบบรหัส (Asset Code Structure): ให้สร้างรหัสทรัพย์สินเฉพาะสำหรับการ Overhaul โดย ต้องอ้างอิงและต่อท้ายรหัสเครื่องจักรคันเดิมเสมอ เช่น ใช้เครื่องหมาย - หรือ / ต่อท้าย'),
  (13, 9, 'caption', 0, 'ตัวอย่าง: เครื่องจักรเดิมรหัส MC-001 เมื่อทำ Overhaul ให้ตั้งรหัสทรัพย์สินใหม่เป็น MC-001-1 หรือ MC-001/O1'),
  (13, 10, 'sub', 1, 'วันที่เริ่มบันทึกทรัพย์สิน (Asset Date / Ready for Use): ให้บันทึกเพิ่มทรัพย์สินในระบบ FA ณ วันที่การซ่อมบำรุง Overhaul เสร็จสมบูรณ์ และเครื่องจักรพร้อมกลับมาใช้งานจริงเท่านั้น (ไม่อนุญาตให้ลงบันทึกทรัพย์สินล่วงหน้าขณะยังซ่อมไม่เสร็จ)'),
  (13, 11, 'sub', 1, 'ปัจจุบัน บริษัทวิจิตรภัณฑ์ก่อสร้างจํากัด ยังมีทรัพย์สินของบริษัท CVN Development รวมอยู่ด้วย ซึ่งจะตั้งรหัสพิเศษขึ้นมาขึ้นต้นด้วย "2" และทำการผูก Account Code แยกจากทรัพย์สินปกติ เพื่อเป็นการแยกกรรมสิทธิ์กันอย่างชัดเจนออกจากทรัพย์สินของวิจิตรภัณฑ์ก่อสร้างที่จะขึ้นต้นรหัสด้วย "1" โดยที่ไม่ได้สร้างเพิ่มใน Multi Company เนื่องจาก CVN ยังไม่มีรายได้ที่จะสามารถดูแลรักษาค่าใช้จ่ายเกี่ยวกับเครื่องจักรได้ ทั้งนี้การ Ref. Asset ซ่อมบำรุงทั้งหมดจะทำในรหัสหมายเลข "2"'),
  (13, 12, 'numbered', 0, 'การกำหนดสถานที่ตั้งเครื่องจักร (Location Code Policy)'),
  (13, 13, 'sub', 1, 'สถานที่วางทรัพย์สิน (Asset Location): ในขั้นตอนการเปิดบันทึกเพิ่มทรัพย์สินสำหรับการ Overhaul ให้ระบุ Location Code เป็น "ศูนย์ซ่อมสาย 5" เท่านั้น'),
  (13, 14, 'sub', 1, 'ข้อห้าม: ห้ามระบุเป็นชื่อโครงการหน้างานโดยเด็ดขาด ในขณะที่ทำการบันทึกรับรู้ทรัพย์สิน Overhaul เข้าระบบ'),
  (13, 15, 'numbered', 0, 'การเชื่อมโยงประวัติและค่าเสื่อมราคา (Depreciation & History Tracking)'),
  (13, 16, 'sub', 1, 'เมื่อบันทึกรับรู้ทรัพย์สิน Overhaul รหัสใหม่เรียบร้อยแล้ว ให้เลือกวิธีคิดค่าเสื่อมราคา (Depreciation Method) ตามอายุการใช้งานที่เพิ่มขึ้นจริงของงาน Overhaul นั้น'),
  (13, 17, 'sub', 1, 'ให้ระบุรหัสทรัพย์สินเดิมในช่อง Ref. Code / Description เพื่อผูกประวัติการซ่อมบำรุงและประวัติค่าใช้จ่ายในรายงาน Asset History Report ของ Module FA'),
  (14, 1, 'numbered', 0, 'วัตถุประสงค์และนโยบายหลัก (Purpose & Core Policies)'),
  (14, 2, 'sub', 1, 'Matching 100%: ชื่อผู้รับประโยชน์/ผู้รับเงินบน หน้าเช็ค (หรือเอกสารโอนเงิน) และ ใบอนุมัติจ่าย (APP / Pre-Payment) รวมถึง ใบสำคัญจ่าย (PV) ต้องตรงกันทุกประการ'),
  (14, 3, 'sub', 1, 'ห้ามแก้ไขด้วยลายมือ (No Manual Alteration): ห้ามทำการขีดฆ่า แก้ไข หรือเขียนเพิ่มเติมชื่อผู้รับเงินด้วยลายมือบนเอกสารที่พิมพ์ออกจากระบบ ERP โดยเด็ดขาด เอกสารที่มีการแก้ไขด้วยลายมือถือเป็นเอกสารโมฆะและไม่สามารถใช้ประกอบการทำจ่ายได้'),
  (14, 4, 'sub', 1, 'ห้ามสั่งจ่ายเช็คเงินสด (No Cash Cheque): ห้ามออกเช็คสั่งจ่าย "เงินสด" (Cash) สำหรับรายการที่มีการตั้งจ่ายในนามบุคคลหรือนิติบุคคลในระบบ ยกเว้นได้รับการอนุมัติเป็นกรณีพิเศษจากฝ่ายบริหาร'),
  (14, 5, 'numbered', 0, 'การอนุมัติจ่ายและการออกเช็ค/โอนเงิน (Approve Payment & Preparing Cheque)'),
  (14, 6, 'caption', 0, '(ผู้รับผิดชอบ: แผนกการเงิน / บัญชี)'),
  (14, 7, 'sub', 1, 'เข้าไปที่โมดูล AP → อนุมัติจ่าย → อนุมัติจ่าย APV/APS/APO'),
  (14, 8, 'sub', 1, 'ตรวจสอบชื่อผู้รับเงิน (Pay To) ให้ตรงกับเจ้าหนี้ตามเอกสารตั้งหนี้'),
  (14, 9, 'sub', 1, 'ระบบจะสร้างเลขที่ชุดอนุมัติจ่าย (Pre-Payment / APP)'),
  (14, 10, 'numbered', 0, 'การจัดทำเช็ค/โอนเงิน (Preparing Cheque / PV): เข้าไปที่โมดูล AP → Preparing Cheque, Credit Line → ชำระโดยเช็ค หรือโอนเงิน'),
  (14, 11, 'sub', 1, 'ดึงชุดอนุมัติจ่ายมาทำรายการสั่งจ่าย โดยระบบจะดึงชื่อผู้รับเงิน (Pay To) และบัญชีธนาคารจากฐานข้อมูล Master มาให้อัตโนมัติ ห้ามผู้ใช้งานเปลี่ยนชื่อผู้รับเงินเป็นเงินสด หรือเปลี่ยนชื่อบุคคลอื่นในขั้นตอนนี้'),
  (14, 12, 'numbered', 0, 'กระบวนการยกเลิก/ถอยเอกสาร เพื่อขออนุมัติใหม่ (Reversal Workflow)'),
  (14, 13, 'caption', 0, '(ผู้รับผิดชอบ: แผนกการเงิน / บัญชี / ผู้มีอำนาจอนุมัติ) กรณีจำเป็นต้องเปลี่ยนแปลงชื่อผู้รับเงิน หรือเปลี่ยนรูปแบบ/วิธีการจ่ายเงิน เนื่องจากการอนุมัติของบริหารครอบคลุมทั้งความเหมาะสมของค่าใช้จ่ายและตัวตนผู้รับเงิน/วิธีการจ่าย ห้ามแก้ไขบนกระดาษ แต่ต้องดำเนินการถอยเอกสารในระบบเพื่อขออนุมัติใหม่ทั้งสายงาน ดังนี้:'),
  (14, 14, 'caption', 0, 'กรณียังไม่ออกเช็ค/PV (ยกเลิกชุดอนุมัติจ่าย):'),
  (14, 15, 'sub', 1, 'เข้าไปที่โมดูล AP → อนุมัติจ่าย → เลือกเมนู ยกเลิกการอนุมัติจ่าย (Cancel Approve Payment)'),
  (14, 16, 'sub', 1, 'เลือกชุดอนุมัติจ่าย (Payment No.) ที่ต้องการยกเลิก ระบุเหตุผลการยกเลิก แล้วกด Save เพื่อปลดล็อกเอกสาร APV/APS/APO กลับไปสู่สถานะรออนุมัติจ่าย'),
  (14, 17, 'caption', 0, 'กรณีมีการบันทึกเช็ค/PV แล้ว:'),
  (14, 18, 'sub', 1, 'ต้องทำการยกเลิกเอกสารใบสำคัญจ่าย (PV) และยกเลิกเช็คในระบบก่อน แล้วจึงมาทำรายการ >ยกเลิกการอนุมัติจ่าย ในโมดูล AP'),
  (14, 19, 'caption', 0, 'การแก้ไขข้อมูลและส่งอนุมัติใหม่:'),
  (14, 20, 'sub', 1, 'ทำการตั้งชุดอนุมัติจ่าย (APP) และส่งให้ผู้บริหารอนุมัติใหม่ตามชื่อเจ้าหนี้/ผู้รับเงินที่ต้องการก่อนทำการพิมพ์เช็ค/โอนเงินอีกครั้ง'),
  (14, 21, 'numbered', 0, 'การติดตามและควบคุมภายใน (Internal Control & Audit)'),
  (14, 22, 'sub', 1, 'ฝ่ายตรวจสอบภายใน (Internal Audit): จะทำการสุ่มตรวจเช็คใบสำคัญจ่าย (PV) สลิปโอนเงิน และสุ่มตรวจเทียบกับชื่อผู้รับเงินในระบบ Mango ERP หากพบรายการขีดฆ่าแก้ไขด้วยลายมือ หรือสั่งจ่ายไม่ตรงกับใบ APP จะถือเป็นข้อบกพร่องร้ายแรงทางด้านการควบคุมภายใน'),
  (15, 1, 'numbered', 0, 'ข้อกำหนดและนโยบายการปฏิบัติงาน (Policy Rules)'),
  (15, 2, 'sub', 1, 'การบันทึกรับใบกำกับภาษีย้อนหลังจะทำได้ เฉพาะรายการที่มีการทำเอกสารตัดเจ้าหนี้ (PL) หรือตัดลูกหนี้ (RL) เสร็จสิ้นสมบูรณ์แล้วเท่านั้น โดยเมื่อได้รับใบเสร็จรับเงิน/ใบกำกับภาษีตัวจริงในภายหลัง ให้นำเอกสารต้นฉบับแนบเข้ากับชุดเอกสารกระดาษของ PL/RL โดยตรง ไม่ต้องทำการสแกนแนบไฟล์ในระบบ ERP'),
  (15, 3, 'numbered', 0, 'ขั้นตอนการปฏิบัติงานในระบบ Mango ERP (System Workflow)'),
  (15, 4, 'caption', 0, 'ขั้นตอนที่ 1: การบันทึกตัดเจ้าหนี้ในระบบ (Clear AP)'),
  (15, 5, 'caption', 0, '(ผู้รับผิดชอบ: แผนกการเงิน)'),
  (15, 6, 'sub', 1, 'เข้าไปที่โมดูล AP → ดำเนินการ → บันทึกตัดเจ้าหนี้/บันทึกรับใบกำกับภาษีย้อนหลัง'),
  (15, 7, 'sub', 1, 'เลือกเมนู บันทึกตัดเจ้าหนี้ (Clear AP) → เลือกรายการเจ้าหนี้ที่ต้องการตัดชำระ ตรวจสอบข้อมูลให้ถูกต้อง แล้วกด Save'),
  (15, 8, 'sub', 1, 'ระบบจะทำการตัดจ่ายเจ้าหนี้ บันทึกยอดเข้าระบบ GL ทันที และสร้างเอกสารใบสำคัญตัดเจ้าหนี้ (PL)'),
  (15, 9, 'caption', 0, 'ขั้นตอนที่ 2: การบันทึกรับใบกำกับภาษีย้อนหลัง (Receive Document Tax)'),
