  (16, 26, 'sub', 2, 'Cr.ธนาคารที่ตัดชำระ/ค่างาน/เบิกใช้ตั๋วPNเพื่อชำระตัวมันเอง(ยกตัวอย่างกรณี CVE)'),
  (17, 1, 'numbered', 0, 'เกณฑ์การบันทึกรายได้และค่าใช้จ่าย (Revenue & Expense Policy)'),
  (17, 2, 'caption', 0, '(มีผลบังคับใช้ตั้งแต่ปี พ.ศ. 2569 เป็นต้นไป)'),
  (17, 3, 'caption', 0, 'บันทึกภายใต้สำนักงานใหญ่ (Head Office):'),
  (17, 4, 'sub', 1, 'รายได้: รายได้จากการคิดค่าเช่าเครื่องจักรทั้งหมด'),
  (17, 5, 'sub', 1, 'ค่าใช้จ่าย: ค่าใช้จ่ายที่เกี่ยวข้องกับทรัพย์สิน และค่าใช้จ่ายเกี่ยวกับพนักงานประจำเครื่องจักร (เช่น เงินเดือนพนักงานขับรถ และพนักงาน Oiler ที่ปฏิบัติงานตามโครงการต่างๆ)'),
  (17, 6, 'caption', 0, 'บันทึกภายใต้โครงการ (Project):'),
  (17, 7, 'sub', 1, 'บันทึกเฉพาะค่าใช้จ่ายที่อยู่ภายใต้งบประมาณของโครงการตาม Master Plan ที่ใช้ประกอบการขออนุมัติสินเชื่อกับธนาคาร'),
  (17, 8, 'numbered', 0, 'เกณฑ์การบันทึกค่าเสื่อมราคาและการโอนย้าย (Depreciation & Asset Transfer)'),
  (17, 9, 'sub', 1, 'การคิดค่าเสื่อมราคาประจำงวด: ให้บันทึกเป็นค่าใช้จ่ายตาม โครงการผู้ถือครองทรัพย์สิน นั้นๆ ณ ปัจจุบัน'),
  (17, 10, 'sub', 1, 'การโอนย้ายทรัพย์สิน (Module FA): เมื่อสิ้นสุดโครงการและมีการโอนย้ายเครื่องจักร ให้ทำรายการโอนย้ายในระบบ ERP โดย ยอดค่าเสื่อมราคาสะสม (Accumulated Depreciation) จะถูกโอนไปยังโครงการใหม่ และคำนวณต่อจากยอดเดิมทันที'),
  (17, 11, 'numbered', 0, 'ขอบเขตผลกระทบและการปฏิบัติงาน (Scope & Operational Impact)'),
  (17, 12, 'sub', 1, 'ผลกระทบ: มีผลเฉพาะการจัดทำ งบการเงินสำหรับผู้บริหาร (Management Financial Statement) เพื่อวิเคราะห์ผลการดำเนินงานเท่านั้น'),
  (17, 13, 'sub', 1, 'การปฏิบัติงานหน้างาน: ไม่มีผลกระทบต่อกระบวนการทำเอกสารหรือขั้นตอนปฏิบัติงานหน้ารายวัน (เช่น PR, PO, OF, IC) พนักงานยังคงปฏิบัติตามขั้นตอนเดิมทุกประการ'),
  (18, 1, 'numbered', 0, 'วัตถุประสงค์และปัญหาเดิม (Problem & Purpose)'),
  (18, 2, 'sub', 1, 'ปัญหาเดิม: การทำรายการจ่ายเงินหรือโอนเงินระหว่างบัญชีภายในบริษัท (ทั้งนิติบุคคลเดียวกันและต่างนิติบุคคล) รวมถึงการบันทึกรายการในสมุดรายวัน (JV) ไม่ได้มีการระบุประเภทรายการรับ-จ่าย (Option) ให้ถูกต้อง ส่งผลให้โมดูล Bank Account Management บนระบบ On-Web ไม่สามารถวิเคราะห์ จัดกลุ่ม และตั้งยอด เดบิต/เครดิต (Debit/Credit) ของแต่ละบัญชีธนาคารได้อย่างถูกต้อง'),
  (18, 3, 'sub', 1, 'วัตถุประสงค์: บังคับใช้มาตรฐานการระบุ Option ทุกครั้งที่มีการคีย์รายการ รับ-โอน-จ่าย เงิน เพื่อให้ข้อมูลวิ่งไปแสดงผลในหน้า Bank Account Management และรายงานกระแสเงินสด (Cash Flow) ได้อย่างแม่นยำแบบ Real-Time'),
  (18, 4, 'numbered', 0, 'ข้อกำหนดและนโยบายการปฏิบัติงาน (Policy Rules)'),
  (18, 5, 'sub', 1, 'บังคับระบุ Option ทุกรายการ: ทุกธุรกรรมที่มีการรับเงิน จ่ายเงิน หรือโอนเงินระหว่างบัญชีธนาคาร (ทั้งในโมดูล AP, AR, FN และ GL/JV) ต้องเลือก Option ให้ตรงตามวัตถุประสงค์จริงเสมอ'),
  (18, 6, 'sub', 1, 'การตั้งค่าล็อกในระบบ (System Control): ให้แผนกบัญชี/Admin ตั้งค่าผังบัญชีธนาคารทุกบัญชี โดยเปิดปุ่ม Warning Option เพื่อให้ระบบแจ้งเตือนและบังคับให้ผู้ใช้งานต้องกรอก Option ก่อนบันทึกเอกสารทุกครั้ง'),
  (18, 7, 'numbered', 0, 'ขั้นตอนการปฏิบัติงานในระบบ Mango ERP (System Workflow)'),
  (18, 8, 'caption', 0, 'ขั้นตอนที่ 1: การตรวจสอบและตั้งค่าข้อมูลหลัก (Master Setup)'),
  (18, 9, 'caption', 0, '(ผู้รับผิดชอบ: ผู้ดูแลระบบ / แผนกบัญชี)'),
  (18, 10, 'sub', 1, 'ตั้งค่า/แก้ไขชื่อกลุ่มรายการรับ-จ่าย: ไปที่ Setup Master → Financial (FN) → จัดกลุ่มรายการรับ-จ่าย (Option Pay / Receipt)'),
  (18, 11, 'sub', 1, 'ตรวจสอบ/แก้ไข หรือเพิ่มรหัส Option Code และ Option Name สำหรับรายการโอนเงินระหว่างบัญชีภายในให้ชัดเจน (เช่น เงินโอนระหว่างบัญชี, เงินโอนข้ามนิติบุคคล)'),
  (18, 12, 'sub', 1, 'เปิดการแจ้งเตือนเตือน Warning Option บนผังบัญชีธนาคาร: ไปที่ Setup Master → Account (บัญชี) → ผังบัญชี (Account Code)'),
  (18, 13, 'sub', 1, 'เลือกรหัสบัญชีธนาคาร (Bank Account) ที่ต้องการ แล้วเปิดสวิตช์ Warning Option'),
  (18, 14, 'sub', 1, 'กด Save บันทึกข้อมูล (เมื่อเปิดปุ่มนี้ ระบบจะล็อกไม่ให้บันทึกเอกสารหากผู้ใช้งานไม่ได้ระบุ Option)'),
  (18, 15, 'caption', 0, 'ขั้นตอนที่ 2: การบันทึกรายการประจำวัน (Daily Transaction Entry)'),
  (18, 16, 'caption', 0, '(ผู้รับผิดชอบ: เจ้าหน้าที่การเงิน / แอดมิน / บัญชี)'),
  (18, 17, 'sub', 1, 'การบันทึกโอนเงิน/ชำระเงินผ่านโมดูลการเงิน/เจ้าหนี้/ลูกหนี้ (AP / AR / FN):'),
  (18, 18, 'sub', 1, 'ในขั้นตอนการคีย์รับ-จ่าย หรือโอนเงินผ่านธนาคาร ให้เลือกระบุช่อง Option Type / Option Name ให้ตรงกับประเภทธุรกรรมการโอนเงินนั้นๆ ทุกครั้ง'),
  (18, 19, 'sub', 1, 'การบันทึกผ่านสมุดรายวันทั่วไป (GL - Journal Voucher / JV):'),
  (18, 20, 'sub', 1, 'เข้าไปที่โมดูล GL → บันทึกสมุดรายวัน (Journal Voucher) → สร้างใบสำคัญ'),
  (18, 21, 'sub', 1, 'ในตารางบันทึกบัญชี (General Ledger) บรรทัดที่เป็นรหัสบัญชีธนาคาร ให้เลื่อนไปที่คอลัมน์ Option แล้วเลือกระบุ Option Name ที่เกี่ยวข้องเสมอ ตรวจสอบความถูกต้องและกด Save'),
  (18, 22, 'numbered', 0, 'การตรวจสอบผลลัพธ์ในระบบ (Verification & Monitoring)'),
  (18, 23, 'caption', 0, '(ผู้รับผิดชอบ: ผู้บริหาร / ฝ่ายการเงิน)'),
  (18, 24, 'sub', 1, 'สามารถเข้าไปตรวจสอบการจัดกลุ่มรายการโอนและยอดคงเหลือ เดบิต/เครดิต ของแต่ละบัญชีธนาคารได้ที่:'),
  (18, 25, 'caption', 0, 'Module PM → Inquiry → Bank Account Management'),
  (18, 26, 'caption', 0, 'ข้อมูลจะแสดงรายรับ (Debit) รายจ่าย (Credit) และยอดเช็คค้างชำระของแต่ละบัญชีธนาคารได้อย่างถูกต้องเพื่อใช้บริหารสภาพคล่องทางการเงิน'),
  (19, 1, 'numbered', 0, 'การแยกแยะประเภทเอกสารและความแตกต่างในระบบ (ผู้รับผิดชอบ: แผนกจัดซื้อ และ แผนกบัญชี)'),
  (19, 2, 'caption', 0, 'ต้องตรวจสอบและแยกแยะประเภทเงินที่จ่ายให้คู่ค้าออกจากกันให้ถูกต้องตั้งแต่ขั้นตอนตกลงสัญญาและจัดทำเอกสารหลัก:'),
  (19, 3, 'sub', 1, 'Advance (เงินจ่ายล่วงหน้า): เป็นเงินจ่ายล่วงหน้าตามเงื่อนไขใบสั่งซื้อ (PO) ซึ่งบันทึกตั้งหนี้ในระบบผ่านหน้าจอ จากการรับสินค้าตาม PO (Type: Down) ยอดเงินนี้สามารถนำมาบันทึกหักลด รายงวด ได้ผ่านขั้นตอนรับของตาม PO Receive หรือหักจากงวดงานผู้รับเหมา'),
  (19, 4, 'sub', 1, 'Deposit (เงินมัดจำ): บันทึกคำขอเบิกเงินสดผ่าน Module OF ➔ Deposit ถือเป็นเงินค้ำประกันสัญญากลาง ไม่สามารถนำมาทำตารางหักลดยอดรายงวดในหน้ารับของ PO ได้ ยอดเงินนี้จะคงค้างเป็นสินทรัพย์ในระบบจนกว่าจะยุติสัญญา และต้องทำเรื่องรับโอนคืนเต็มจำนวน (Refund/Return) เท่านั้น'),
  (19, 5, 'numbered', 0, 'ขั้นตอนการบันทึกบัญชีและการบริหาร Rolling Credit ในระบบ (ผู้รับผิดชอบ: แผนกบัญชี)'),
  (19, 6, 'sub', 1, 'เมื่อบริษัทจ่ายเงินล่วงหน้าตาม PO ให้ทำการตั้งหนี้ในระบบที่ Module AP ➔ ตั้งหนี้ ➔ จากการรับสินค้าตาม PO โดยเลือกประเภทการตั้งหนี้ (Type) เป็น Down เพื่อบันทึกยอดเป็น "เงินจ่ายล่วงหน้าค่าสินค้า (Advance)"'),
  (19, 7, 'sub', 1, 'ในแต่ละงวดเมื่อคู่ค้าส่งมอบสินค้าและวางบิล ให้แผนกบัญชีบันทึกรับของเต็มจำนวนโดย "ไม่มีการระบุค่าหัก Less Adv. ออกจากยอดจ่าย" เพื่อรักษายอดเครดิตหมุนเวียน (Rolling Credit) และลดภาระของคู่ค้าในการถอนและเปลี่ยนเช็คหรือเอกสารค้ำประกันในทุกๆ รอบงวด'),
  (19, 8, 'sub', 1, 'เมื่อบริษัทต้องการ "ยุติการซื้อขาย" หรือจบโครงการร่วมกัน ให้แผนกบัญชีเข้าทำการปรับปรุงบัญชีล้างยอด โดยนำยอดตั้งหนี้ค่าสินค้าลอตสุดท้าย (APV) มาทำรายการหักล้าง (Offset) กับยอดบัญชี Advance สะสมที่คงค้างทั้งหมดในระบบ เพื่อเคลียร์ยอดคงเหลือของคู่ค้ารายนั้นให้เป็นศูนย์'),
  (19, 9, 'numbered', 0, 'นโยบายการคืนหลักประกันและการจัดการงวดสุดท้าย (Guarantee Return & Final Settlement)'),
  (19, 10, 'sub', 1, '(ผู้รับผิดชอบ: แผนกจัดซื้อ และ แผนกวิศวกรรมโครงการ) ➔ ในช่วง 2–3 งวดสุดท้ายของการซื้อขาย แผนกจัดซื้อต้องประสานงานกับแผนกวิศวกรรมโครงการเพื่อร่วมกันวางแผนการสั่งซื้อและตรวจสอบยอดวางบิล เพื่อให้มั่นใจว่างวดงานที่เหลืออยู่จะเพียงพอต่อการตัดยอดเงิน Advance สะสมได้ครบถ้วนทั้งหมดภายในรอบการซื้อขายนั้นๆ'),
  (19, 11, 'sub', 1, '(ผู้รับผิดชอบ: แผนกการเงิน) ➔ บริษัทกำหนดเงื่อนไขในการคืนเอกสารค้ำประกัน เช่น เช็คค้ำประกัน หรือหนังสือค้ำประกันธนาคาร (Bank Guarantee - BG) กลับคืนให้แก่คู่ค้า ต่อเมื่อยอดเงิน Advance ในระบบได้รับการหักล้างจนครบถ้วน 100% แล้วเท่านั้น หากยอดเงิน Advance ยังค้างคาหรือร้านค้ายังไม่สามารถคืนเงินส่วนต่างให้บริษัทได้ครบถ้วน ห้ามทำการส่งคืนเอกสารหลักประกันค้ำประกันให้แก่คู่ค้าเด็ดขาด'),
  (19, 12, 'sub', 1, '(ผู้รับผิดชอบ: แผนกจัดซื้อ และ แผนกบัญชี) ➔ ในกรณีที่สุดวิสัย ยอดส่งสินค้าในงวดสุดท้ายมีมูลค่าไม่เพียงพอสำหรับการหักล้างเงิน Advance ให้ดำเนินการประสานงานให้ร้านค้าทำการ โอนเงินสดส่วนต่างคงเหลือทั้งหมดคืนเข้าบัญชีธนาคารของบริษัท และออก ใบลดหนี้ (Credit Note - CN) สำหรับยอดเงิน Advance ส่วนที่ยังไม่ได้หักล้างส่งมอบให้แผนกบัญชี เพื่อใช้ประกอบการบันทึกปรับปรุงบัญชีและรายงานภาษีให้ถูกต้อง'),
  (20, 1, 'numbered', 0, 'การนำเข้าและตั้งค่าควบคุมงบประมาณในหมวด BD (Module BD)'),
  (20, 2, 'caption', 0, '(ผู้รับผิดชอบ: ฝ่ายประเมินราคา / วิศวกรสำนักงาน / แอดมิน BD)'),
  (20, 3, 'caption', 0, 'การนำเข้า BOQ/Budget และระบุ Job Code:'),
  (20, 4, 'sub', 1, 'เข้าโมดูล BD → Transaction → Bill of Quantity (BOQ)'),
  (20, 5, 'sub', 1, 'ทำการ Import ไฟล์งบประมาณ/BOQ เข้าระบบ'),
  (20, 6, 'sub', 1, 'ในช่อง Job Code สำหรับงาน Civil Work ให้กรอกเป็น " ''001 " ทุกรายการ'),
  (20, 7, 'numbered', 0, 'การตั้งค่าควบคุมงบประมาณ (Control Budget):'),
  (20, 8, 'sub', 1, 'ก่อนส่งเอกสารขออนุมัติงบประมาณ ต้องทำเครื่องหมายถูก (Check) ที่ช่อง "Control Budget" (หรือเลือกเป็น By Summary Cost Code) เสมอ เพื่อเปิดระบบการควบคุมต้นทุน'),
  (20, 9, 'sub', 1, 'การปรับขยายวงเงินราย Item: ค่า Default ของระบบจะตั้งไว้ที่ 100% หากหน้างานมีความจำเป็นต้องขยายวงเงินเฉพาะบางรายการ ให้เข้าไปที่หน้า Project Budget (แท็บ Cost Code Summary / Setup % Control) เพื่อแก้ไขปรับเพิ่ม % Control ให้รองรับการทำงานจริง'),
  (20, 10, 'numbered', 0, 'การตั้งค่าควบคุมปริมาณวัสดุ (Control Material QTY):'),
  (20, 11, 'sub', 1, 'หากต้องการควบคุมปริมาณวัสดุเพิ่มเติม ต้องระบุรหัสวัสดุ (Material Code) ให้ครบถ้วนทุกรายการ'),
  (20, 12, 'sub', 1, 'จากนั้นทำเครื่องหมายถูกที่ช่อง "Control BOQ" หรือ "Control by Summary" (ในแท็บ Summary Material) เพื่อให้ระบบล็อกปริมาณการขอซื้อ/ขอเบิกไม่ให้เกิน BOQ'),
  (20, 13, 'numbered', 0, 'การตั้งค่างบประมาณประมาณการล่วงหน้าในหมวด PM (Module PM)'),
  (20, 14, 'caption', 0, '(ผู้รับผิดชอบ: แผนกวิศวกรรม )'),
  (20, 15, 'sub', 1, 'เข้าสู่โมดูล PM → Transaction → Project Forecast Expected Cost (Forecast Budget)'),
  (20, 16, 'sub', 1, 'ค้นหาและเลือกรหัสโครงการ (Project No.) ที่ต้องการ'),
  (20, 17, 'sub', 1, 'ไปที่แท็บ Budget แล้วให้แผนกวิศวกรรมกดปุ่ม "Copy Forecast Budget" (หรือ Init. Budget Cost) ระบบจะทำการดึงยอดงบประมาณปัจจุบัน (Current Budget) มากรอกในช่อง Forecast ให้อัตโนมัติ'),
  (20, 18, 'sub', 1, 'ตรวจสอบความถูกต้องของตัวเลขงบประมาณ แล้วกดปุ่ม Save (บันทึก) ข้อมูลจะถูกนำไปใช้ประมวลผลต่อในรายงาน Project Status Overview, S-Curve Graph และรายงานวิเคราะห์สภาพคล่องของโมดูล PM ทันที'),
  (21, 1, 'numbered', 0, 'การเคลียร์เงินทดรองจ่าย (Clear Advance) และค่าอะไหล่ซ่อมแซม ให้แอดมินโครงการไปที่โมดูล OF → ดำเนินการ → ใบเบิกเงินสดย่อยและใบเบิกจ่ายที่ไม่มี PO/WO เลือกประเภทเอกสาร (Document Type) เป็น Clear Advance ทำการระบุชื่อผู้เบิกเงินทดรองและโครงการให้ตรงกับตอนที่ตั้งเรื่องเบิก Advance'),
  (21, 2, 'sub', 1, 'กรณีเป็นค่าอะไหล่ซ่อมแซม (ไม่เข้าสต๊อก): ที่แท็บรายการ ให้เลือก "รหัสค่าใช้จ่าย" เป็นกลุ่ม "อะไหล่ซ่อมแซม" และในช่อง รายละเอียดเพิ่มเติม (Remark) ให้ระบุ เลขที่อ้างอิงทรัพย์สิน/เครื่องจักร และรายละเอียดอะไหล่ให้ครบถ้วน'),
  (21, 3, 'sub', 1, 'จากนั้นกดปุ่ม "เงินทดรองจ่าย" เพื่อดึงยอด Advance เดิมมาหักล้าง (ระบบจะคำนวณส่วนต่างและล้างยอด APO ค้างให้อัตโนมัติ โดยไม่ต้องผ่านกระบวนการใบเตรียมจ่าย) กด Save และส่งอนุมัติ'),
  (21, 4, 'sub', 1, 'หากเป็นการเบิกเงินไปเพื่อซื้อของเข้าสต๊อก ควรให้จัดซื้อเปิด PR/PO แทนการใช้เงิน Advance เพื่อป้องกันปัญหาสินค้าตกหล่นจากการไม่มี PO Receipt'),
  (21, 5, 'numbered', 0, 'การคืนอะไหล่ส่วนที่ใช้ไม่หมดเข้าสต๊อก (Manual IC Receive)'),
  (21, 6, 'sub', 1, 'ให้แอดมินโครงการ ไปที่โมดูล IC → Document IC Receive → Stock Receive (รับวัสดุเข้าคลัง) ระบุคลังสินค้า (Warehouse) ที่ต้องการนำอะไหล่ไปเก็บ'),
  (21, 7, 'sub', 1, 'บันทึกรับรหัสวัสดุ (อะไหล่) กลับเข้าคลัง โดยระบุจำนวน (QTY) ที่เหลือจริง และ ใส่มูลค่าต่อหน่วย (Price/Unit) เป็น 0 ตามนโยบาย กด Save เพื่ออัปเดตยอดคงเหลือในสต๊อก'),
  (21, 8, 'sub', 1, 'หากอะไหล่เหลือมีมูลค่าน้อยมาให้ข้ามขั้นตอนนี้ และบันทึกเป็นค่าใช้จ่ายเต็มจำนวนในส่วนที่ 1 ได้เลย'),
  (21, 9, 'numbered', 0, 'การตั้งรหัสและรับของเข้าทรัพย์สิน (กรณีซ่อมข้ามนิติบุคคล)'),
  (21, 10, 'sub', 1, 'กรณีนำอะไหล่ไปซ่อมข้ามนิติบุคคล และต้องตั้งรหัสทรัพย์สินเฉพาะกลุ่ม: ให้แผนกบัญชีทรัพย์สินไปที่โมดูล FA → บันทึกรายการ → บันทึกเพิ่มทรัพย์สิน (Entry Asset)'),
  (21, 11, 'sub', 1, 'Asset Code (รหัสทรัพย์สิน): ให้ระบุรหัสโดยขึ้นต้นด้วย "Z" ตามนโยบาย'),
  (21, 12, 'sub', 1, 'Depreciation (การคิดค่าเสื่อม): ให้เลือกเป็น "No" (ไม่คิดค่าเสื่อม)'),
  (21, 13, 'sub', 1, 'Description (รายละเอียดเพิ่มเติม): ให้ระบุหมายเหตุว่า "ทรัพย์สินเก่าก่อนขึ้นระบบ"'),
  (21, 14, 'sub', 1, 'ระบุข้อมูลอื่นๆ ให้ครบถ้วน (เช่น ประเภททรัพย์สิน, สถานที่ตั้ง, รหัสบัญชี)'),
  (21, 15, 'sub', 1, 'ตรวจสอบความถูกต้องและกด Save ระบบจะสร้างฟอร์มใบบันทึกข้อมูลทรัพย์สิน'),
  (21, 16, 'numbered', 0, 'การบันทึกประวัติการซ่อมบำรุงและค่าใช้จ่ายของเครื่องจักร (ผู้รับผิดชอบ: แผนกบัญชี / ช่างซ่อมบำรุง) เพื่อให้แผนกบัญชีสามารถตรวจสอบประวัติการซ่อมและจำนวนอะไหล่ที่ใช้กับเครื่องจักรแต่ละเครื่องได้อย่างถูกต้อง:'),
  (21, 17, 'sub', 1, 'หลังจากเคลียร์เอกสารในโมดูล OF แล้ว ให้ไปที่โมดูล FA → บันทึกรายการ → บันทึกค่าใช้จ่ายเกี่ยวกับทรัพย์สิน → บันทึกค่าบำรุงรักษาและค่าใช้จ่าย'),
  (21, 18, 'sub', 1, 'เลือก Asset Code (รหัสทรัพย์สินเครื่องจักร/รถยนต์ ที่ทำการซ่อม)'),
  (21, 19, 'sub', 1, 'ที่ช่อง Maintenance/Cost code ให้เลือกรหัสค่าใช้จ่ายซ่อมแซม'),
  (21, 20, 'sub', 1, 'ระบุจำนวน (Qty) ของอะไหล่ และจำนวนเงิน (Amount) ค่าซ่อมแซมที่เกิดขึ้นจริง'),
  (21, 21, 'sub', 1, 'ระบุรายละเอียดในช่อง Description ให้ชัดเจน (เช่น เปลี่ยนอะไหล่ชิ้นไหน) แล้วกด Save'),
  (21, 22, 'sub', 1, 'เมื่อบันทึกข้อมูลส่วนนี้ ข้อมูลจะถูกเก็บเป็น "ประวัติการซ่อมบำรุงเครื่องจักร" ซึ่งสามารถเรียกดูรายงาน (Maintenance Report) ได้อย่างครบถ้วนในอนาคต'),
  (22, 1, 'numbered', 0, 'ให้ทุกโครงการเลือกชื่อโครงการหลักเท่านั้นในทุก Module ของระบบ ERP ห้ามสร้างหรือเลือกชื่อโครงการในลักษณะห้อยท้าย เช่น "บางเตย ตอน 1 – ศูนย์ซ่อมสาย 5" เนื่องจากระบบ ERP จะตีความว่าเป็นคนละโครงการ ส่งผลให้เกิด Budget Misallocation ทันที'),
  (22, 2, 'numbered', 0, 'หากต้องการระบุประเภทค่าใช้จ่าย เช่น งานซ่อมบำรุง ให้ใช้ Cost Code / หมวดค่าใช้จ่ายในระบบ ERP สำหรับการรายงานและการแสดง Report เท่านั้น ห้ามแก้ไขชื่อโครงการเพื่อสื่อความหมายของค่าใช้จ่ายโดยเด็ดขาด'),
  (22, 3, 'numbered', 0, 'ผู้ดูแลระบบและผู้ที่ได้รับมอบหมายสิทธิ์ในการแก้ไขข้อมูลโครงการ ให้งดการสร้างโครงการหรือ Loop อนุมัติใดๆ ที่ขัดหรือแย้งกับหลักการนี้'),
  (23, 1, 'numbered', 0, 'กรณีการเปิด PR (Purchase Requisition):'),
  (23, 2, 'sub', 1, 'งานก่อสร้างปกติที่ต้องการเปิดใบสั่งซื้อ (PO): ให้โครงการเป็นผู้เปิด PR เอง โดยเลือกชื่อโครงการหลักและใช้ Loop PR010: อนุมัติเอกสาร PR (โครงการ-PO)'),
  (23, 3, 'sub', 1, 'งานก่อสร้างปกติที่ต้องการเปิดใบสั่งจ้าง (WO): ให้โครงการแจ้งความประสงค์มายังแผนกวิศวกรรมสำนักงานใหญ่ เพื่อให้ทางวิศวะสำนักงานใหญ่เปิด PR ที่ถูกต้องผ่าน Loop PR012: อนุมัติเอกสาร PR (โครงการ-WO)'),
  (23, 4, 'sub', 1, 'งานซ่อมบำรุงเครื่องจักรและทรัพย์สิน: ให้โครงการแจ้งความประสงค์มายังสาย 5 เท่านั้น เพื่อให้ทางสาย 5 เปิด PR ที่ถูกต้องผ่าน Loop PR007: อนุมัติเอกสาร PR (โครงการ-ซ่อมเครื่องจักร) โดยผ่านการอนุมัติของผู้จัดการศูนย์ซ่อม สาย 5 และหัวหน้าแผนกพัสดุทรัพย์สิน'),
  (23, 5, 'sub', 1, 'ค่าใช้จ่ายของสาย 5 โดยตรง (ไม่เกี่ยวข้องกับโครงการ): ให้เลือก Project เป็น "ศูนย์ซ่อมเครื่องจักรกล พุทธมณฑลสาย 5" เท่านั้น'),
  (23, 6, 'numbered', 0, 'กรณีการเปิด OF (Office Service):'),
  (23, 7, 'sub', 1, 'งานก่อสร้างปกติภายในประเทศ: ให้โครงการหลักเป็นผู้เปิด OF เข้ามาเอง โดยใช้ Loop OF-B002 และ OF-B003: อนุมัติเอกสารเงินทดรองจ่ายและจ่ายอื่นๆ (โครงการในประเทศ)'),
  (23, 8, 'sub', 1, 'งานก่อสร้างปกติต่างประเทศ: ให้โครงการหลักเป็นผู้เปิด OF เอง โดยใช้ Loop OF-B004 และ OF-B005: อนุมัติเอกสารเงินทดรองจ่ายและจ่ายอื่นๆ (โครงการต่างประเทศ)'),
  (23, 9, 'sub', 1, 'งานซ่อมบำรุงเครื่องจักรและทรัพย์สิน: ให้โครงการแจ้งความประสงค์มายังสาย 5 (เช่นเดียวกับกรณี PR) ทางสาย 5 จะเปิด OF ผ่าน Loop OF-B007 และ OF-B008: อนุมัติเอกสารเงินทดรองจ่ายและจ่ายอื่นๆ (ค่าซ่อมเครื่องจักร) โดยเลือกโครงการที่จะทำการซ่อม และส่งอนุมัติผ่านผู้จัดการศูนย์ซ่อม สาย 5 และหัวหน้าแผนกทรัพย์สิน โดยอนุญาตให้พนักงานสาย 5 สามารถเข้าถึงทุกโครงการ (Multi-Company) เพื่อให้สามารถเลือกโครงการที่ถูกต้องในการเปิด PR ซ่อมเครื่องจักรได้อย่างเหมาะสม ทั้งนี้โครงการอื่นจะไม่มีสิทธิ์เปิด PR งานซ่อมบำรุงเอง'),
  (23, 10, 'sub', 1, 'ค่าเงินเดือน ภงด.1 กยส., ประกันสังคม, ค่าสวัสดิการต่างๆ ของพนักงาน, ค่าธรรมเนียมธนาคาร, ค่าภาษีต่าง ๆ ที่ไม่อยู่ภายใต้หลักการดูแลของแผนกวิศวกรรม ให้เปิดผ่าน Loop OF-B000 และ OF-B001: อนุมัติเอกสารเงินทดรองจ่ายและจ่ายอื่นๆ (บริหาร) โดยพนักงานของสำนักงานใหญ่เท่านั้น'),
  (24, 1, 'numbered', 0, 'ข้อกำหนดและนโยบายหลัก'),
  (24, 2, 'sub', 1, 'การบันทึกตามผลงานที่ Certify จริง: ในเบื้องต้น เพื่อลดขั้นตอนการทำงานและป้องกันความคลาดเคลื่อนของข้อมูล ให้ฝ่ายวิศวกรรมบันทึกยอดเงินขอเบิกโดยอ้างอิงจาก "ใบตรวจรับงาน" (Certify Progress) ที่ได้รับการเซ็นรับมอบและรับรองผลงานจริงจากผู้ว่าจ้าง/เจ้าของโครงการแล้วเท่านั้น'),
  (24, 3, 'sub', 1, 'การส่งต่อข้อมูลข้ามโมดูล: เมื่อทำการบันทึกและตรวจรับรองในโมดูล OF เสร็จสิ้นแล้ว แผนกบัญชีจึงจะสามารถดึงยอดดังกล่าวไปเปิดใบแจ้งหนี้ (Invoice) ในโมดูล AR เพื่อบันทึกตั้งลูกหนี้ได้อย่างถูกต้อง'),
  (24, 4, 'numbered', 0, 'การบันทึกขอเบิกเงินส่งมอบงาน (ฝ่ายวิศวกรรม / หน้าโครงการ)'),
  (24, 5, 'sub', 1, 'เข้าสู่โมดูล OF → ดำเนินการ → บันทึกความคืบหน้าของโครงการ → กดปุ่ม ส่งมอบงานโครงการ (Progress Submit)'),
  (24, 6, 'sub', 1, 'วันที่: ระบุวันที่ของเอกสารส่งมอบงาน'),
  (24, 7, 'sub', 1, 'โครงการ: กดค้นหาและเลือกรหัสโครงการที่ต้องการเรียกเก็บเงิน (ระบบจะดึงข้อมูลลูกหนี้/เจ้าของโครงการมาแสดงให้อัตโนมัติ)'),
  (24, 8, 'sub', 1, 'ประเภทรับวางบิล: เลือกเป็น Progress Payment'),
  (24, 9, 'sub', 1, 'รายละเอียดเพิ่มเติม: ระบุงวดงาน หรือรายละเอียดการส่งมอบ'),
  (24, 10, 'sub', 1, 'ไปที่แท็บ Job: ระบุยอดเงินที่ต้องการเบิกจริงตามใบตรวจรับงานที่ผู้ว่าจ้าง Certify แล้วลงในช่อง Amount'),
  (24, 11, 'sub', 1, 'ตรวจสอบความถูกต้องแล้วกดปุ่ม Save (บันทึก) เพื่อให้ระบบสร้างแบบฟอร์ม ใบขอเบิกเงิน (Progress Submit Form)'),
  (24, 12, 'numbered', 0, 'การตรวจสอบและรับรองผลงาน (Submit Certificate)'),
  (24, 13, 'sub', 1, 'ในหน้าต่าง เอกสารส่งมอบงานโครงการ (Progress Submit) ให้กดค้นหาเอกสารรายการที่ได้บันทึกไว้'),
  (24, 14, 'sub', 1, 'กดปุ่ม Submit Certificate (หรือยืนยันส่งตรวจสอบผลงาน) ระบบจะ Auto ยอดเงินในช่อง Amount Certification ให้เท่ากับยอดเงินขอเบิก (หากยอดเงินที่ได้รับอนุมัติจริงตรงตามที่ Certify ให้ยืนยันยอดดังกล่าว)'),
  (24, 15, 'sub', 1, 'ระบุวันที่ผู้ว่าจ้างอนุมัติรับรองผลงานในช่อง Certification Date'),
  (24, 16, 'sub', 1, 'ตรวจสอบข้อมูลแล้วกด Save (บันทึก) เพื่อเปลี่ยนสถานะเอกสารเป็น Certificated (รับรองผลงานเรียบร้อยแล้ว)'),
  (24, 17, 'numbered', 0, 'การเปิดใบแจ้งหนี้และตั้งลูกหนี้ (แผนกบัญชีและการเงิน)'),
  (24, 18, 'caption', 0, '(ผู้รับผิดชอบ: เจ้าหน้าที่บัญชีลูกหนี้ AR)'),
  (24, 19, 'sub', 1, 'เข้าสู่โมดูล AR → บันทึกรายการ → บันทึกใบแจ้งหนี้ (Create Invoice) → จากสัญญาในโครงการ (Progress Payment)'),
  (24, 20, 'sub', 1, 'กดปุ่มค้นหาที่ช่อง เลขที่ใบรับรองอ้างอิง (Ref. Certification No.) เลือกเอกสาร Submit-Certification ที่ฝ่ายวิศวกรรมทำรายการรับรองผลงานมาจากโมดูล OF'),
  (24, 21, 'sub', 1, 'ตรวจสอบยอดเงิน วันที่ และรายละเอียดภาษีให้ถูกต้อง จากนั้นกด Save (บันทึก) เพื่อสร้างใบแจ้งหนี้ (Invoice) และบันทึกตั้งหนี้ลูกหนี้ในระบบ'),
  (24, 22, 'numbered', 0, 'การเชื่อมโยงและประมวลผลข้อมูล (Impact on PM & FN Modules)'),
  (24, 23, 'sub', 1, 'เมื่อดำเนินกระบวนการตั้งแต่ OF (Progress Submit → Submit Cert.) ถึง AR (Create Invoice) เรียบร้อยแล้ว ยอดรายรับจะวิ่งไปประมวลผลในระบบให้อัตโนมัติ ดังนี้:'),
  (24, 24, 'sub', 1, 'โมดูล PM: แสดงยอดผลงานจริงที่ทำได้ (Actual Progress / Progress Submit) และยอดการตั้งหนี้ (Invoiced) ในหน้า Project Status Overview และกราฟ S-Curve'),
  (24, 25, 'sub', 1, 'โมดูล FN: ดึงยอดไปแสดงใน Dashboard ประมาณการรายได้ส่งผลงานวางอินวอยซ์ถึงเก็บเงินได้จริง (Dashboard 5 & 6) และรายงาน Cash Flow เพื่อวิเคราะห์สภาพคล่องทางการเงิน'),
  (25, 1, 'numbered', 0, 'การซื้อขายน้ำมันกรณี "ใช้ถังน้ำมันร่วมกัน" ณ จุดเดียวกัน (Shared Fuel Tank)'),
  (25, 2, 'caption', 0, '(ใช้สำหรับไซต์งานที่รถของหลายบริษัทในเครือวิ่งเข้ามาเติมน้ำมันจากถังเก็บเดียวกัน)'),
  (25, 3, 'caption', 0, 'ขั้นตอนที่ 1.1: การเตรียมเอกสารตั้งต้นและการเปิด PO (เปิด 2 ฉบับ)'),
  (25, 4, 'sub', 1, '[PO ฉบับที่ 1 - ซื้อน้ำมันเข้าถังกลาง (บริษัท A ➔ ร้านค้าภายนอก)]'),
  (25, 5, 'sub', 2, '[แผนกจัดซื้อ] เปิดใบสั่งซื้อ (PO) ในนาม บริษัท A เพื่อสั่งซื้อน้ำมันจากร้านค้า'),
  (25, 6, 'sub', 2, '[แอดมินบริษัท A] เมื่อน้ำมันมาส่งจริง ทำการบันทึกรับของเข้าคลัง (PO Receive) เพื่อนำเนื้อน้ำมันทั้งหมดเข้าระบบสต๊อกของบริษัท A ตามราคาทุนจริงที่ซื้อ'),
  (25, 7, 'sub', 1, '[PO ฉบับที่ 2 - ซื้อเพื่อเบิกใช้งานข้ามบริษัท (บริษัท B ➔ ซื้อจาก บริษัท A)]'),
  (25, 8, 'sub', 2, '[แผนกจัดซื้อ] เปิดใบสั่งซื้อ (PO) ในนาม บริษัท B โดยระบุผู้ขายเป็น "บริษัท A" (อ้างอิงราคาตามที่ตกลงกัน โดยยืนราคาเดือนต่อเดือน และอิงปริมาณตาม PR คลุมรายเดือนที่วิศวกรหน้างานประมาณการ +10%)'),
  (25, 9, 'caption', 0, 'ขั้นตอนที่ 1.2: การบันทึกรับ-จ่ายหน้างานจริงเมื่อมีการเติมน้ำมัน (Real-time Transaction)'),
  (25, 10, 'sub', 2, '[ฝั่งบริษัท A (ผู้ขาย)]: เมื่อรถของบริษัท B วิ่งมาเติมน้ำมันจากถังกลาง ➔ [แอดมินบริษัท A] ทำรายการเบิกจ่าย (Issue) ในระบบ IC ➔ ระบุ Area Code เป็นประเภท "คิดเงิน" (เพื่อตัดปริมาณน้ำมันออกจากคลังของบริษัท A และส่งข้อมูลไปตั้งยอดขาย)'),
  (25, 11, 'sub', 2, '[ฝั่งบริษัท B (ผู้ซื้อ)]: [แอดมินบริษัท B] ทำการบันทึกรับของ (PO Receive) โดยอ้างอิง PO ฉบับที่ 2 ทันที เพื่อบันทึกน้ำมันที่เติมจริงเข้าสต๊อกและลงเป็นต้นทุนโครงการของบริษัท B ตามปริมาณที่จ่ายจริง'),
  (25, 12, 'caption', 0, 'ขั้นตอนที่ 1.3: กระบวนการทางบัญชีและการปิดยอด (Accounting Closure)'),
  (25, 13, 'sub', 2, '[แผนกบัญชี บริษัท A]: ดึงเอกสารรับของ (PO Receive) จาก PO ฉบับที่ 1 มาบันทึกตั้งหนี้ APV ในระบบ เพื่อทำเรื่องเสนออนุมัติจ่ายชำระเงินค่าสินค้าให้แก่ "ร้านค้าภายนอก"'),
  (25, 14, 'sub', 2, '[แผนกบัญชี บริษัท A (ผู้ขาย)] ดึงยอดการเบิกจ่ายจริงทั้งหมดจากสโตร์ผ่าน Module AR ➔ เลือกประเภทรายการเป็น "Trading" (ซื้อมาขายไป) ➔ ดำเนินการออกใบกำกับภาษีขายโดยบวกกำไรเพิ่ม 1% ส่งให้บริษัท B'),
  (25, 15, 'sub', 2, '[แผนกบัญชี บริษัท B (ผู้ซื้อ)] ดึงเอกสารรับของจาก PO ฉบับที่ 2 มาบันทึกตั้งหนี้ (APV) ตามรอบบัญชีเพื่อรอทำจ่ายชำระเงินคืนให้แก่บริษัท A'),
  (25, 16, 'numbered', 0, 'การซื้อขายน้ำมันกรณี "ถังน้ำมันแยกกันคนละพื้นที่" (Separate Fuel Tanks - ขายยกล็อต)'),
  (25, 17, 'caption', 0, '(ใช้สำหรับกรณีที่บริษัท B มีถังน้ำมันของตัวเองแยกต่างหาก แต่อยากสั่งซื้อน้ำมันจากคลังของบริษัท A เพื่อไปลงที่ถังของตนเอง)'),
  (25, 18, 'caption', 0, 'ขั้นตอนที่ 2.1: การเตรียมเอกสารและการสั่งซื้อ (เปิด PO 2 ฉบับ)'),
  (25, 19, 'sub', 1, '[PO ฉบับที่ 1 - ซื้อน้ำมันมาพักคลัง (บริษัท A ➔ ร้านค้าภายนอก)]'),
  (25, 20, 'sub', 2, '[แผนกจัดซื้อ] เปิด PO ซื้อน้ำมันจากภายนอกเข้าสู่ถังคลังของ บริษัท A และสโตร์บันทึกรับของ (PO Receive) ตามปกติ'),
  (25, 21, 'sub', 1, '[PO ฉบับที่ 2 - ซื้อน้ำมันยกล็อต (บริษัท B ➔ ซื้อจาก บริษัท A)]'),
  (25, 22, 'sub', 2, '[แผนกจัดซื้อ] เปิดใบสั่งซื้อ (PO) ในนาม บริษัท B โดยระบุผู้ขายเป็น "บริษัท A" (อ้างอิงราคาตามที่ตกลงกัน โดยยืนราคาเดือนต่อเดือน และอิงปริมาณตาม PR คลุมรายเดือนที่วิศวกรหน้างานประมาณการ +10%)'),
  (25, 23, 'caption', 0, 'ขั้นตอนที่ 2.2: การรับของและการทำรายการคู่ขนาน (Parallel PO Receive & Bulk IC Issue)'),
  (25, 24, 'sub', 1, '[ฝั่งบริษัท B - บันทึกรับของจริง]: เมื่อรถน้ำมันส่งมอบน้ำมันลงถังของ บริษัท B เรียบร้อย ➔ [แอดมินบริษัท B] เซ็นรับใบส่งสินค้าและทำการบันทึกรับของเข้าคลัง (PO Receive) อ้างอิง PO ฉบับที่ 2 ทันที เพื่ออัปเดตยอดสต๊อกในไซต์ B'),
  (25, 25, 'sub', 1, '[แผนกบัญชี บริษัท B] ดึงข้อมูลจากเอกสารรับของ (PO Receive) ดังกล่าวมาทำการบันทึกตั้งหนี้ (APV) ได้ทันทีโดยไม่ต้องรอเอกสารจาก บริษัท A (ระบบบันทึกเป็นเจ้าหนี้ค้างจ่าย Unbilled AP เพื่อล็อกต้นทุนเข้าโครงการทันที)'),
  (25, 26, 'sub', 1, '[การส่งต่อหลักฐาน]: [แอดมินบริษัท B] ถ่ายรูปใบส่งสินค้าที่เซ็นรับเรียบร้อยแล้ว ส่งแชร์เข้ากลุ่ม Line หรือ Email ร่วมทันที'),
  (25, 27, 'sub', 1, '[ฝั่งบริษัท A - บันทึกรับของเข้าระบบ (PO Receive)]: [แอดมินบริษัท A] เมื่อเห็นรูปใบส่งสินค้าในกลุ่ม ➔ ทำการบันทึกรับของเข้าคลัง (PO Receive) อ้างอิง PO ฉบับที่ 1 ควบคู่ทันที เต็มจำนวนตามที่ B ได้รับ เพื่อให้บัญชีมีหลักฐานตั้งหนี้จ่ายชำระเงินให้ร้านค้าภายนอก'),
  (25, 28, 'sub', 1, '[ฝั่งบริษัท A - บันทึกตัดจ่ายยกล็อตทันที (Immediate Bulk IC Issue) ➔ [แอดมินบริษัท A] ต้องทำการบันทึกเบิกจ่าย (IC Issue) ยอดน้ำมันทั้งหมดเต็มจำนวนทันที ➔ โดยระบุ Area Code เป็นประเภท "คิดเงิน" เพื่อตัดยอดสต๊อกน้ำมันออกจากคลังของ บริษัท A'),
  (25, 29, 'sub', 1, '[แผนกบัญชี บริษัท A (ผู้ขาย)]: ดึงข้อมูลการเบิกจ่ายยกล็อต (IC Issue) ผ่าน Module AR (Trading) เพื่อออกใบกำกับภาษีขาย โดยบวกกำไรส่วนต่าง 1% ส่งให้แก่บริษัท B'),
  (26, 1, 'numbered', 0, 'ข้อกำหนดและนโยบายหลัก (Core Policy Rules)'),
  (26, 2, 'sub', 1, 'ห้ามจ่ายเงินก่อนมียอดอนุมัติจ่าย (No Payment without Approved Pre-payment): การจ่ายเงินทุกกรณี (เงินสด, เช็ค, ตั๋วสัญญาใช้เงิน หรือช่องทางอื่น ๆ) ต้องมีเอกสารชุดอนุมัติจ่าย (APP / Pre-payment) ในระบบรองรับก่อนเสมอ ห้ามโอนเงินหรือตัดเช็คออกจากระบบล่วงหน้าโดยเด็ดขาด'),
  (26, 3, 'sub', 1, 'การสั่งซื้อวัสดุต้องมี PO รองรับเสมอ: โครงการต้องมีใบสั่งซื้อ (PO) ที่ผ่านการอนุมัติล่วงหน้า เพื่อใช้สำหรับรับของเข้าคลัง (PO Receive / IC Receive) ให้ถูกต้องตามปริมาณจริง'),
  (26, 4, 'sub', 1, 'การบันทึกข้อมูลแบบ Real-Time: ผู้เกี่ยวข้องต้องเร่งบันทึกเอกสารตามลำดับขั้นตอนในระบบทันทีเพื่อไม่ให้กระทบต่อการตั้งหนี้และการอนุมัติจ่ายของแผนกบัญชีการเงิน'),
  (26, 5, 'numbered', 0, 'ขั้นตอนการปฏิบัติงานในระบบ Mango ERP (System Workflow)'),
  (26, 6, 'caption', 0, 'ลำดับที่ 1: สายงานจัดซื้อวัสดุ/สินค้า (Materials & Goods Process)'),
  (26, 7, 'sub', 1, 'ใบขอซื้อ (PR): โครงการเปิด PR และส่งอนุมัติผ่านระบบ'),
  (26, 8, 'sub', 1, 'ใบสั่งซื้อ (PO): ฝ่ายจัดซื้อเปิด PO อ้างอิงจาก PR และส่งอนุมัติตามสายงาน'),
  (26, 9, 'sub', 1, 'การรับสินค้าเข้าสต๊อก (PO Receive / IC Receive): เมื่อสินค้ามาส่ง โครงการต้องบันทึกรับของผ่านโมดูล IC หรือ PO ทันที เพื่อให้ยอดสินค้าเข้าคลังอย่างถูกต้อง'),
  (26, 10, 'sub', 1, 'การตั้งหนี้ (APV): แผนกบัญชีดึงรายการรับสินค้า (PO Receive) มาบันทึกตั้งสำคัญตั้งหนี้ (APV)'),
  (26, 11, 'sub', 1, 'การอนุมัติจ่าย (APP): แผนกการเงินตั้งชุดอนุมัติจ่าย (APP / Pre-payment) เสนอผู้บริหารอนุมัติ'),
  (26, 12, 'sub', 1, 'การจ่ายเงิน (PV / Cheque / Promissory Note): ออกเช็ค โอนเงิน หรือบันทึกการจ่ายตั๋วสัญญาใช้เงินผ่านชุดอนุมัติจ่ายในระบบ'),
  (26, 13, 'caption', 0, 'ลำดับที่ 2: สายงานค่าใช้จ่ายทั่วไป/บริการที่ไม่มี PO/WO (Office & Other Expenses Process)'),
  (26, 14, 'sub', 1, 'ใบเบิกเงิน (OF): ผู้ขอเบิกจัดทำเอกสารเบิกจ่ายในโมดูล OF และส่งอนุมัติ'),
  (26, 15, 'sub', 1, 'การตั้งหนี้ (APO): แผนกบัญชีดึงเอกสาร OF มาบันทึกตั้งใบสำคัญตั้งหนี้อื่นๆ (APO)'),
  (26, 16, 'sub', 1, 'การอนุมัติจ่าย (APP): ตั้งชุดอนุมัติจ่าย (APP / Pre-payment) เสนออนุมัติ'),
  (26, 17, 'sub', 1, 'การทำจ่าย (PV): ดำเนินการชำระเงินตามชุดอนุมัติจ่าย'),
  (26, 18, 'numbered', 0, 'แนวทางปฏิบัติกรณีฉุกเฉินและการย้อนหลัง (Emergency Procedure)'),
  (26, 19, 'sub', 1, 'ผู้ประสานงาน/โครงการ ต้องแจ้งผู้เกี่ยวข้องให้ดำเนินการเปิดเอกสารตั้งต้น (PR / PO / WO / OF) และตั้งหนี้ (APV / APO) ในระบบให้เสร็จสิ้น ภายในวันทำการถัดไปโดยเร็วที่สุด'),
  (26, 20, 'sub', 1, 'การระบุหมายเหตุ (Remark): ในขั้นตอนการคีย์เอกสารย้อนหลัง ผู้จัดทำต้องระบุในช่อง Remark / Comment ชัดเจนว่าเป็น "รายการตั้งเบิกย้อนหลัง เนื่องจากจ่ายเงินฉุกเฉินเมื่อวันที่ [ระบุวันที่]" เพื่อเน้นย้ำและป้องกันไม่ให้แผนกบัญชี/การเงิน ทำรายการจ่ายเงินซ้ำซ้อน (Double Payment)'),
  (26, 21, 'caption', 0, 'และรายงาน Pending Purchase Requisition ในโมดูล OF'),
  (26, 22, 'caption', 0, 'เพื่อกระตุ้นให้หน้างานเร่งส่งเอกสารได้ทันท่วงทีครับ'),
  (27, 1, 'numbered', 0, 'กรณีเพิ่มผู้ใช้งาน (User) ใหม่'),
  (27, 2, 'sub', 1, 'ให้สร้าง User ใน บริษัท วิจิตรภัณฑ์ก่อสร้าง จำกัด ก่อนเสมอ'),
  (27, 3, 'numbered', 0, 'กรณีแก้ไขสิทธิ์การใช้งาน (User Rights)'),
  (27, 4, 'sub', 1, 'ให้ดำเนินการแก้ไขใน บริษัท วิจิตรภัณฑ์ก่อสร้าง จำกัด ก่อนเสมอ โดยทำการ “Copy Template User Rights” ปัจจุบัน จาก Template Group ที่กำหนดไว้ 13 กลุ่มหลักสำหรับแต่ละตำแหน่งงาน ไปยังพนักงานที่ต้องการ'),
  (27, 5, 'sub', 1, 'หลังจากตรวจสอบความถูกต้องแล้ว ให้ดำเนินการ “Copy User to Company” เพื่อคัดลอก User และ User Rights ไปยังบริษัทอื่นในเครือตามลำดับ'),
  (27, 6, 'numbered', 0, 'กรณีตั้งค่าสิทธิการมองเห็นโครงการ (Project Rights)'),
  (27, 7, 'sub', 1, 'ให้กำหนดสิทธิการมองเห็นโครงการตาม รายบุคคล สำหรับ แต่ละ Company เนื่องจากสิทธิการเข้าถึงโครงการของแต่ละบริษัทอาจแตกต่างกัน'),
  (27, 8, 'numbered', 0, 'กรณีตั้งค่าสิทธิ์การมองเห็นคลังสินค้า (Site IC)'),
  (27, 9, 'sub', 1, 'ให้กำหนดสิทธิ์การมองเห็นรายบุคคล โดยให้พัสดุประจำโครงการสามารถมองเห็นแค่โครงการที่ตัวเองรับผิดชอบ และในกรณีจำเป็นต้องมองเห็นเพิ่มเติม เช่น การใช้ถังน้ำมันร่วมกัน ให้แจ้งเป็นรายกรณีไป'),
  (28, 1, 'numbered', 0, 'ข้อกำหนดและนโยบายหลัก (Core Policy Rules)'),
  (28, 2, 'caption', 0, 'อ้างอิงตามสัญญาระหว่างบริษัทแม่และกิจการร่วมค้า (JV) ให้ยึดหลักการในการตีความทรัพย์สินดังนี้:'),
  (28, 3, 'sub', 1, 'กรรมสิทธิ์หลัก: เครื่องจักรเป็นกรรมสิทธิ์ของ "บริษัท วิจิตรภัณฑ์ก่อสร้าง จำกัด" หรือ "ชวนาเอ็นจิเนียร์ริ่ง จำกัด" เท่านั้น (บริษัทแม่)'),
  (28, 4, 'sub', 1, 'กรรมสิทธิ์ส่วนควบ: อะไหล่ หรืออุปกรณ์ใดๆ ที่จัดซื้อและนำมาติดตั้งเข้ากับเครื่องจักร จะตกเป็นกรรมสิทธิ์ของบริษัทแม่ในทันที (ถือว่าทรัพย์สินดังกล่าวไม่เคยเป็นกรรมสิทธิ์ของ JV แม้จะจัดซื้อในนาม JV ก็ตาม)'),
  (28, 5, 'sub', 1, 'ความรับผิดชอบค่าใช้จ่าย: กิจการร่วมค้า (JV) เป็นผู้รับผิดชอบเรื่องค่าใช้จ่ายเกี่ยวกับเครื่องจักรทั้งหมดตามสัญญา'),
  (28, 6, 'numbered', 0, 'ขั้นตอนการปฏิบัติงานในระบบ Mango ERP (System Workflow)'),
  (28, 7, 'caption', 0, 'เพื่อให้ประวัติเครื่องจักรเชื่อมโยงกันอย่างถูกต้อง ให้แบ่งการทำงานออกเป็น 2 ส่วน (ทำใน 2 ฐานข้อมูลของบริษัท) ดังนี้:'),
  (28, 8, 'sub', 1, 'ส่วนที่ 1: การดำเนินงานในฝั่งกิจการร่วมค้า (JV) – รับผิดชอบค่าใช้จ่าย'),
  (28, 9, 'caption', 0, '(ผู้รับผิดชอบ: ฝ่ายจัดซื้อ / แอดมินประจำโครงการ JV / ศูนย์ซ่อมสาย 5)'),
  (28, 10, 'sub', 2, 'การขอซื้อและสั่งซื้อ (PR/PO): ให้ศูนย์ซ่อมเครื่องจักรสาย 5 เปิดใบขอซื้อ (PR) และฝ่ายจัดซื้อเปิดใบสั่งซื้อ (PO) ในระบบ ERP ของฝั่ง JV เพื่อเป็นหลักฐานการสั่งซื้อและรับผิดชอบค่าใช้จ่ายให้กับร้านค้าตามเงื่อนไขของธนาคาร'),
  (28, 11, 'sub', 2, 'การรับเข้าคลัง (IC Receive): เมื่อของมาส่งหน้างาน ให้แอดมินโครงการทำการรับสินค้าเข้าคลังในระบบของ JV ตามปกติ'),
  (28, 12, 'sub', 2, 'การตัดจ่ายออกจากระบบ JV (IC Issue): ให้แอดมินโครงการฝั่ง JV ทำการเบิกของออก (Issue) เพื่อตัดสต๊อก โดยให้ระบุช่อง Area Code เป็น 005 "ปรับปรุงยอด" เพื่อให้ทราบวัตถุประสงค์ว่าเป็นการตัดอะไหล่ออกเพื่อส่งมอบกรรมสิทธิ์ให้บริษัทแม่ (ไม่ต้องทำขั้นตอน AR)'),
  (28, 13, 'sub', 1, 'ส่วนที่ 2: การดำเนินงานในฝั่งบริษัทแม่ – บันทึกประวัติทรัพย์สิน'),
  (28, 14, 'caption', 0, '(ผู้รับผิดชอบ: แอดมินร์ส่วนกลาง และ ส่วนซ่อมสาย 5)'),
  (28, 15, 'sub', 2, 'การนำอะไหล่เข้าระบบบริษัทแม่ (Receive Other): เมื่อฝั่ง JV ตัดของออกแล้ว ให้ศูนย์ซ่อมเครื่องจักรสาย 5 ทำการรับอะไหล่/อุปกรณ์ดังกล่าวเข้าคลังของบริษัทแม่ โดยใช้ฟังก์ชันรับเข้าอื่นๆ (Receive Other) ในโมดูล IC'),
  (28, 16, 'sub', 2, 'การเบิกเข้าเครื่องจักร (Issue to Fixed Asset): ให้ทำการเปิดใบเบิกวัสดุ (IC Issue) ในระบบของบริษัทแม่ โดยระบุการเบิกจ่ายเพื่อนำไปติดตั้งเข้ากับ รหัสเครื่องจักร (Asset Code) คันนั้นๆ โดยตรง'),
  (28, 17, 'sub', 2, 'ผลลัพธ์การบันทึกประวัติ: ข้อมูลอะไหล่และมูลค่าอุปกรณ์ทั้งหมดจะวิ่งไปเก็บเป็นประวัติการซ่อมบำรุง (Maintenance History) ที่โมดูล FA (Fixed Asset) ของบริษัทแม่ ทำให้ประวัติเครื่องจักรครบถ้วน ไม่สูญหายแม้โครงการ JV จะปิดไปแล้ว'),
  (29, 1, 'numbered', 0, 'การบันทึกค่าใช้จ่ายตั้งต้นเข้าโครงการหลัก (Module OF)'),
  (29, 2, 'caption', 0, '(ผู้รับผิดชอบ: ฝ่ายธุรการ หรือ แผนกบัญชีทั่วไป)'),
  (29, 3, 'sub', 1, 'ขั้นตอนปฏิบัติ: ดำเนินการเปิดใบเบิกเงินสดย่อย หรือ ใบเบิกจ่ายอื่น ๆ ตามประเภทค่าใช้จ่าย เช่น ค่าไฟ ค่าน้ำ ค่าสำนักงาน โดยในช่อง "โครงการ/แผนก" ให้เลือกโครงการหลักคือ "สำนักงานชวนา" เพื่อรวบรวมค่าใช้จ่ายส่วนกลางทั้งหมดไว้ที่นี่ก่อน'),
  (29, 4, 'numbered', 0, 'การตั้งค่าหัวข้อการปันส่วน (Module GL ➔ Setup Allocate Subject)'),
  (29, 5, 'caption', 0, '(ผู้รับผิดชอบ: แผนกบัญชี หรือ บัญชีบริหาร)'),
  (29, 6, 'sub', 1, 'ขั้นตอนปฏิบัติ: (ทำเพียงครั้งแรกที่มีการตั้งค่า) ไปที่เมนู Module GL ➔ Report ➔ เลือก 14. Allocate (Depreciation/Expense) ➔ Setup ➔ เลือก 14.2.1 Subject กด เพิ่มรายการ และกำหนดข้อมูลดังนี้:'),
  (29, 7, 'sub', 1, 'Code / Name: กำหนดรหัสและชื่อการปันส่วน (เช่น ปันส่วนค่าใช้จ่ายสำนักงานชวนา)'),
  (29, 8, 'sub', 1, 'DR A/C Cost: เลือกรหัสบัญชีปันส่วนโครงการ (บัญชีค่าใช้จ่ายที่จะวิ่งเข้าโครงการย่อยเป้าหมาย)'),
  (29, 9, 'sub', 1, 'CR A/C Contra: เลือกรหัสบัญชีในการหักล้างค่าเดบิต (บัญชีค่าใช้จ่ายที่ต้องการเครดิตออกจากโครงการ "สำนักงานชวนา")'),
  (29, 10, 'sub', 1, 'กำหนดโครงการรับปันส่วน: ในส่วนของโครงการเป้าหมายปลายทางที่จะรับปันส่วน ให้เพิ่มรหัสโครงการย่อย "ไลน์ผลิตโครงการ บางเตย-บ้านพร้าว ตอน 1" และ "ตอน 2" เข้าไปในรายการเพื่อเป็นโครงการเป้าหมายในฐานข้อมูลเดียวกัน แล้วกดบันทึก'),
  (29, 11, 'numbered', 0, 'การกำหนดสัดส่วนการปันส่วนตามรายได้ (Module GL ➔ Setup QTY of Use)'),
  (29, 12, 'caption', 0, '(ผู้รับผิดชอบ: แผนกบัญชี หรือ บัญชีบริหาร)'),
  (29, 13, 'sub', 1, 'ขั้นตอนปฏิบัติ: (ดำเนินการเป็นประจำทุกเดือนเพื่ออัปเดตสัดส่วนตามยอดเงินที่ผลิตได้จริง)'),
  (29, 14, 'sub', 1, 'ไปที่เมนู Module GL ➔ Report ➔ เลือก 14. Allocate (Depreciation/Expense) ➔ Setup ➔ เลือก 14.2.2 QTY of Use'),
  (29, 15, 'sub', 1, 'ดึงหัวข้อการปันส่วนที่สร้างไว้ในข้อ 2 ขึ้นมา พร้อมระบุวันที่/เดือนที่ต้องการคำนวณ'),
  (29, 16, 'sub', 1, 'ในคอลัมน์สุดท้ายของแต่ละโครงการย่อย ให้ระบุสัดส่วนการปันส่วนที่คำนวณได้จริงในเดือนนั้นๆ (เช่น คำนวณจากสัดส่วนรหัสบัญชีรายได้ที่แต่ละโครงการย่อยผลิตเงินได้จริง)'),
  (29, 17, 'caption', 0, 'กดบันทึกข้อมูล'),
  (29, 18, 'numbered', 0, 'การสร้างสมุดรายวันปันส่วนค่าใช้จ่ายอัตโนมัติ (Module GL ➔ Journal Voucher)'),
  (29, 19, 'caption', 0, '(ผู้รับผิดชอบ: แผนกบัญชีทั่วไป)'),
  (29, 20, 'sub', 1, 'ขั้นตอนปฏิบัติ: เข้าเมนู Module GL ➔ บันทึกสมุดรายวัน (Journal Voucher) ➔ สร้างใบสำคัญ (Create GL)'),
  (29, 21, 'sub', 1, 'ระบุรายละเอียดหัวเอกสารให้ครบถ้วน'),
  (29, 22, 'sub', 1, 'กดปุ่มเมนูด้านซ้ายเพื่อดึงข้อมูลอัตโนมัติ และเลือกฟังก์ชัน "Allocate Expense"'),
  (29, 23, 'sub', 1, 'ระบบจะดึงยอดค่าใช้จ่ายจากโครงการ "สำนักงานชวนา" มาทำรายการเครดิตออก (CR) และ>กระจายเดบิตเข้า (DR) โครงการย่อยปลายทางทั้ง 2 โครงการตามสัดส่วนที่ระบุในหน้า QTY of Use ให้อัตโนมัติ'),
  (29, 24, 'sub', 1, 'ตรวจสอบความถูกต้องของตัวเลขเดบิต/เครดิต บันทึกเอกสาร (Save) และส่งอนุมัติ'),
  (30, 1, 'numbered', 0, 'การบันทึกรับรู้การจ่ายวัสดุออกจากคลังทันที (Real-time IC Recording)'),
  (30, 2, 'sub', 1, '(ผู้รับผิดชอบ: แอดมินประจำโครงการ) ➔ เมื่อมีการจ่ายวัสดุออกจากคลังสินค้าหน้างานจริง (เช่น เหล็ก, ปูน) จะต้องทำการบันทึกรายการจ่ายออกผ่านระบบ Module IC ทันทีตามเวลาที่เกิดขึ้นจริง เพื่อให้ระบบบันทึกยอดสต๊อกคงเหลือได้ถูกต้องแบบ Real-time และห้ามสะสมเอกสารเพื่อบันทึกย้อนหลังเกิน 1 วันทำการอย่างเด็ดขาด'),
  (30, 3, 'sub', 1, '(ผู้รับผิดชอบ: ผู้ขอเบิก / วิศวกรโครงการ / โฟร์แมนหน้างาน) ➔ ดำเนินการจัดทำเอกสารขอเบิกวัสดุในระบบผ่านเมนู Module IC ➔ Transaction ➔ Document IC Issue ➔ Entry Document เพื่อจองปริมาณวัสดุในระบบไว้ก่อนจ่ายจริง โดยต้องกำหนดรายละเอียดประเภทวัสดุ จำนวน QTY และเลือกระบุรหัสพื้นที่ใช้งานในช่อง Area Code รวมถึงระบุชื่อผู้รับเหมาและเลขที่เอกสารสัญญาจ้าง (WO) ให้ชัดเจน เพื่อระบุว่าเป็นการเบิกใช้งานปกติ หรือเป็นการเบิกของไปให้ผู้รับเหมาแบบ "คิดเงิน" (Charge) หรือ "ไม่คิดเงิน" (No Charge)'),
  (30, 4, 'sub', 1, '(ผู้รับผิดชอบ: แอดมินประจำโครงการ) ➔ บันทึกเอกสารตัดจ่ายสินค้าออกจากคลังจริงในระบบผ่านเมนู Module IC ➔ Transaction ➔ Document IC Issue ➔ Stock Issue โดยกดดึงเอกสารขอเบิก (Entry Document) ที่บันทึกไว้ในข้อ 2 ขึ้นมาตรวจสอบความถูกต้องของรายการและกดยืนยันบันทึก เพื่อให้ยอดสต๊อกในระบบถูกหักออกอย่างเป็นทางการ ซึ่งสถานะสินค้าจะถูกเปลี่ยนเป็นยอดที่เบิกออกไปแล้ว (QTY Out Booked)'),
  (30, 5, 'sub', 1, '(ผู้รับผิดชอบ: แอดมินประจำโครงการ) ➔ สั่งพิมพ์แบบฟอร์มใบเบิกวัสดุ (IC Issue) จากระบบ และนำเอกสารฉบับจริงส่งให้ผู้รับของฝ่ายผู้รับเหมาลงนามรับสินค้าเพื่อใช้เป็นหลักฐานยืนยันทางกายภาพ ณ คลังสินค้าหน้างาน ถือเป็นการสิ้นสุดกระบวนการจ่ายของหน้าคลัง'),
  (30, 6, 'numbered', 0, 'การหักค่าใช้จ่ายวัสดุออกจากผลงานผู้รับเหมา (Material Deduction & Verification)'),
  (30, 7, 'sub', 1, '(ผู้รับผิดชอบ: แผนกบัญชีเจ้าหนี้) ➔ เมื่อผู้รับเหมาส่งมอบผลงานงวดงานและมีการทำเรื่องเบิกเงิน (Progress Billing) ในระบบผ่านเมนู Module OF ➔ บันทึกรายการ ➔ บันทึกรับงานของผู้รับเหมา/บันทึกเบิกตามใบสั่งจ้าง ➔ เลือก Progress Payment ระบบจะทำการเชื่อมโยงข้อมูลจากระบบคลังและดึงยอดหักค่าใช้จ่ายวัสดุทั้งหมดที่ระบุเบิกแบบคิดเงิน (Charge) ที่ผูกอยู่กับรหัสผู้รับเหมาและใบสั่งจ้าง (WO) นั้นๆ มาแสดงเพื่อนำมาหักลดจากยอดจ่ายงวดปัจจุบันในช่อง Deduct Material (หักค่าวัสดุ) อัตโนมัติในหน้าต่างรับวางบิล'),
  (30, 8, 'sub', 1, '(ผู้รับผิดชอบ: ฝ่ายควบคุมต้นทุน / แผนกวิศวกรรมโครงการ และ แผนกบัญชีสำนักงานใหญ่) ➔ ร่วมกันตรวจสอบความถูกต้องของยอดหักค่าวัสดุสุทธิที่แสดงในระบบ โดยทำการเปรียบเทียบกับเงื่อนไขในใบสั่งจ้าง (Work Order - WO) และบันทึกข้อตกลงที่ระบุไว้ในสัญญาจ้างอย่างละเอียด เพื่อตรวจสอบยอดให้ตรงกันก่อนทำการอนุมัติตั้งหนี้ (APV) เพื่อจ่ายเงินงวดถัดไป'),
  (30, 9, 'numbered', 0, 'นโยบายการคิดราคาสินค้าและการเบิกจ่ายกรณีพิเศษ (Pricing & Approval Policy)'),
  (30, 10, 'sub', 1, '(ผู้รับผิดชอบ: แผนกจัดซื้อ และ แผนกบัญชีบริหาร) ➔ การกำหนดราคาสินค้าที่จะนำมาคิดเงินและหักยอดเงินกับผู้รับเหมา ให้ใช้การคำนวณราคาตามลำดับสินค้าที่รับเข้าคลังจริง (ราคา FIFO) เพื่อความเป็นธรรมและง่ายต่อการติดตามต้นทุน และกำหนดนโยบายให้ทำการ บวกค่าดำเนินการเพิ่มอีก 4% (Handling Fee) ของมูลค่าวัสดุสุทธิ เพื่อครอบคลุมค่าธรรมเนียมและค่าดำเนินการบริหารจัดการของบริษัทในการจัดหาวัสดุ'),
  (30, 11, 'sub', 1, '(ผู้รับผิดชอบ: ผู้ขอเบิก / วิศวกรโครงการ และ กรรมการผู้จัดการ) ➔ ในกรณีฉุกเฉินหรือกรณีที่มีความจำเป็นต้องจ่ายวัสดุให้แก่ผู้รับเหมาโดยเป็นแบบ "ไม่คิดเงิน" (No Charge) ผู้ขอเบิกต้องทำการส่งเอกสารขออนุมัติในระบบผ่านขั้นตอนสายอนุมัติพิเศษรหัส ICM012: อนุมัติเอกสารใบเตรียมเบิก/โอนวัสดุ (เบิกไม่คิดเงิน) เพื่อส่งเสนอขอความเห็นชอบและอนุมัติจากฝ่ายบริหารระดับสูงและกรรมการผู้จัดการก่อน แอดมินโครงการจึงจะสามารถดำเนินการทำ Stock Issue ปล่อยของออกจากสต๊อกได้'),
  (31, 1, 'numbered', 0, 'ฝั่ง Company A (บริษัทแม่) — ซื้อรถยนต์และขึ้นทะเบียนทรัพย์สิน'),
  (31, 2, 'sub', 1, '[แผนกจัดซื้อ - Company A] บันทึกเปิดใบสั่งซื้อ (PO) ซื้อรถยนต์จากดีลเลอร์ภายนอกในระบบ'),
  (31, 3, 'sub', 1, '[แผนกบัญชี - Company A] บันทึกรับของ (PO Receive) และทำการขึ้นทะเบียนสินทรัพย์ (Asset Registration) ใน Module FA'),
  (31, 4, 'sub', 1, '[แผนกบัญชี - Company A] บันทึกตั้งหนี้ดีลเลอร์ (APV) ในระบบ'),
  (31, 5, 'sub', 1, '[แผนกการเงิน - Company A] บันทึกทำจ่ายเงิน (PV) โดยใช้เงินสดสำรองโอนจ่ายชำระตรงให้แก่ดีลเลอร์รถยนต์ เพื่อปิดบัญชีเจ้าหนี้และนำรถออกมาใช้งาน'),
  (31, 6, 'numbered', 0, 'ฝั่ง Company B (JV) — เบิกเงินกู้จากธนาคารเข้าโครงการ'),
  (31, 7, 'sub', 1, '[แผนกการเงิน - Company B] ยื่นเอกสารเบิกเงินกู้ (Loan Drawdown) กับธนาคาร โดยแนบเอกสาร PO และหลักฐานการจ่ายเงินของ Company A เพื่อแสดงว่ามีกิจกรรมจัดซื้อเพื่อโครงการจริง'),
  (31, 8, 'sub', 1, '[แผนกการเงิน - Company B] เมื่อธนาคารโอนเงินกู้กลับเข้ามาที่บัญชีของ JV ให้ทำการบันทึกรับเงินกู้ยืมใน'),
  (31, 9, 'numbered', 0, 'ขั้นตอนการเรียกเก็บและจ่าย "ค่าเช่ารายเดือน" (Monthly Rental Process)'),
  (31, 10, 'sub', 1, '[แผนกบัญชี - Company A (ผู้ให้เช่า)] ทุกสิ้นเดือน บันทึกออกใบแจ้งหนี้/ใบกำกับภาษี "ค่าเช่ารถยนต์" ใน Module AR (Service/Rental) ส่งไปเก็บเงินที่ Company B'),
  (31, 11, 'sub', 1, '[แผนกบัญชี - Company B (ผู้เช่า)] บันทึกตั้งหนี้ค่าเช่า (APV) เป็นต้นทุนค่าเช่าของโครงการ JV'),
  (31, 12, 'sub', 1, '[แผนกการเงิน - Company B] บันทึกทำจ่ายเงิน (PV) โอนเงินค่าเช่ารถยนต์รายเดือน จากบัญชีธนาคารของ JV ไปยังบัญชีธนาคารของ Company A'),
  (31, 13, 'sub', 1, '[แผนกการเงิน - Company A] บันทึกรับเงินค่าเช่ารายเดือน (RV) ในระบบฝั่ง Company A เพื่อตัดยอดลูกหนี้การค้าของ Company B ให้เรียบร้อย');
